/* TRUCK TALK ENGLISH — 60-Day Curriculum Data (v2: 20 vocab words/day) */
const CURRICULUM = [
{"d":1,"w":1,"wt":"Survival English & Introductions","t":"Greetings & Introducing Yourself","tu":"Salomlashish va O'zingizni Tanishtirish","v":[["Hello / Hi","Salom","Hello, my name is Bekzod."],["Good morning","Xayrli tong","Good morning! Ready for the road?"],["My name is...","Mening ismim...","My name is Aziz. I am a truck driver."],["Nice to meet you","Tanishganimdan xursandman","Nice to meet you, sir."],["Where are you from?","Siz qayerliksiz?","Where are you from? — I am from Uzbekistan."],["I am a truck driver","Men haydovchiman","I am a truck driver for Speedline Logistics."],["Good afternoon","Kunduzgi salom","Good afternoon! How is your trip going?"],["Good evening","Kechki salom","Good evening, sir. I have a delivery for you."],["Goodbye","Xayr","Goodbye, drive safe!"],["See you tomorrow","Ertaga ko'rishguncha","See you tomorrow at the warehouse."],["Excuse me","Kechirasiz","Excuse me, where is the dispatch office?"],["Sir / Ma'am","Janob / Xonim","Yes, sir, I understand."],["Welcome","Xush kelibsiz","Welcome to the company, we're glad to have you."],["How's it going?","Ishlar qalay?","Hey, how's it going today?"],["I'm doing well","Men yaxshiman","I'm doing well, thank you for asking."],["Please","Iltimos","Please wait here for a moment."],["Thank you very much","Katta rahmat","Thank you very much for your help."],["You're welcome","Arzimaydi","You're welcome, happy to help."],["Sorry","Kechirasiz / Uzr","Sorry, I am a few minutes late."],["What's your name?","Ismingiz nima?","What's your name? — My name is Farrux."]],"dl":[["Dispatcher","Hello, are you the new driver?","Salom, siz yangi haydovchimisiz?"],["Driver","Yes, hello! My name is Sardor.","Ha, salom! Mening ismim Sardor."],["Dispatcher","Nice to meet you, Sardor. Where are you from?","Tanishganimdan xursandman, Sardor. Qayerliksiz?"],["Driver","I am from Uzbekistan. I am a new truck driver.","Men O'zbekistondanman. Men yangi haydovchiman."],["Dispatcher","Welcome to the team! Good morning tomorrow at 6 AM.","Jamoaga xush kelibsiz! Ertaga ertalab soat 6 da ko'rishamiz."]],"g":["Subject + am/is/are","Use 'I am' for yourself, 'you are' for the other person, 'he/she is' for someone else. Example: I am a driver. He is a dispatcher."],"qz":[["How do you say 'Salom' in English?",["Goodbye","Hello","Thank you","Please"],1],["Complete: 'My name ___ Aziz.'",["am","is","are","be"],1],["What do you say when you meet someone for the first time?",["See you later","Nice to meet you","I am tired","Good night"],1],["'Where are you from?' is asking about your...",["job","age","country","truck"],2]],"sp":["Introduce yourself: say your name, your country, and your job in 3 sentences.","O'zingizni tanishtiring: ismingiz, mamlakatingiz va kasbingizni 3 ta gapda ayting."]},
{"d":2,"w":1,"wt":"Survival English & Introductions","t":"Numbers & Personal Information","tu":"Raqamlar va Shaxsiy Ma'lumotlar","v":[["Phone number","Telefon raqami","What is your phone number?"],["Address","Manzil","My address is 220 Oak Street."],["Date of birth","Tug'ilgan sana","My date of birth is March 5, 1990."],["License number","Guvohnoma raqami","Please read your license number."],["Social Security number","Ijtimoiy sug'urta raqami","I need your Social Security number for the form."],["Zip code","Pochta indeksi","The zip code is 75201."],["Age","Yosh","What is your age? — I am 32 years old."],["Marital status","Oilaviy holat","Please write your marital status on the form."],["Emergency contact","Favqulodda holat uchun aloqa","List an emergency contact number."],["Employee ID","Xodim identifikatsiya raqami","Your employee ID is on your badge."],["Cell phone number","Uyali telefon raqami","What is your cell phone number?"],["Email address","Elektron pochta manzili","Please write your email address clearly."],["City","Shahar","Which city do you live in?"],["State","Shtat","I live in the state of Texas."],["Country","Mamlakat","My home country is Uzbekistan."],["Apartment number","Kvartira raqami","My address includes apartment number 4B."],["Middle name","O'rta ism (otasining ismi)","Do you have a middle name?"],["Next of kin","Eng yaqin qarindosh","Please list your next of kin."],["Hire date","Ishga qabul qilingan sana","Your hire date is written on the contract."],["Fill out the form","Formani to'ldirmoq","Please fill out the form completely."]],"dl":[["Clerk","What is your full name, please?","Iltimos, to'liq ismingizni ayting."],["Driver","My name is Otabek Yusupov.","Mening ismim Otabek Yusupov."],["Clerk","And your phone number?","Va telefon raqamingiz?"],["Driver","It is 555-201-4478.","555-201-4478."],["Clerk","What is your date of birth?","Tug'ilgan sanangiz qachon?"],["Driver","July 14, 1988.","1988-yil 14-iyul."]],"g":["Saying numbers","Say phone numbers one digit at a time: 555-201-4478 = five five five, two zero one, four four seven eight. Say '0' as 'zero' or 'oh'."],"qz":[["How do you say phone numbers in English?",["As one big number","One digit at a time","Only in Uzbek","You don't say them"],1],["'Date of birth' means...",["Today's date","The day you were born","Your work start date","Your license expiry date"],1],["Which word means 'manzil'?",["Number","Address","Name","License"],1],["A zip code is a...",["Phone code","Postal/area code","License type","Truck model"],1]],"sp":["Say your phone number and date of birth out loud, one digit and one word at a time.","Telefon raqamingiz va tug'ilgan sanangizni ovoz chiqarib, bir-bir ayting."]},
{"d":3,"w":1,"wt":"Survival English & Introductions","t":"The Alphabet & Spelling on the Radio","tu":"Alifbo va Radio Orqali Harflash","v":[["Alpha, Bravo, Charlie","Radio alifbosi (A, B, C)","Alpha, Bravo, Charlie, Delta, Echo..."],["Can you spell that?","Buni harflab bera olasizmi?","Can you spell your last name, please?"],["How do you spell...?","...qanday yoziladi?","How do you spell 'Tashkent'?"],["Capital letter","Bosh harf","Write it with a capital letter."],["Repeat, please","Iltimos, qaytaring","I didn't hear you — repeat, please."],["Loud and clear","Aniq va baland","Copy, loud and clear."],["Delta","D harfi (radio alifbosi)","Delta, Echo, Foxtrot — keep going."],["Echo","E harfi (radio alifbosi)","E as in Echo."],["Foxtrot","F harfi (radio alifbosi)","F as in Foxtrot."],["Golf","G harfi (radio alifbosi)","G as in Golf."],["Hotel","H harfi (radio alifbosi)","H as in Hotel."],["India","I harfi (radio alifbosi)","I as in India."],["Juliett","J harfi (radio alifbosi)","J as in Juliett."],["Kilo","K harfi (radio alifbosi)","K as in Kilo."],["Lima","L harfi (radio alifbosi)","L as in Lima."],["Mike","M harfi (radio alifbosi)","M as in Mike."],["November","N harfi (radio alifbosi)","N as in November."],["Oscar","O harfi (radio alifbosi)","O as in Oscar."],["Papa","P harfi (radio alifbosi)","P as in Papa."],["Quebec","Q harfi (radio alifbosi)","Q as in Quebec."]],"dl":[["Dispatcher","Can you spell your last name for me?","Familiyangizni harflab bera olasizmi?"],["Driver","Yes. J - U - R - A - Y - E - V.","Ha. J - U - R - A - Y - E - V."],["Dispatcher","Juraev, got it. And your load number?","Juraev, tushundim. Yuk raqamingiz-chi?"],["Driver","Load number: Tango, four, seven, one, two.","Yuk raqami: Tango, to'rt, yetti, bir, ikki."],["Dispatcher","Copy that. Loud and clear.","Qabul qildim. Aniq va baland eshitildi."]],"g":["Using the NATO alphabet","Truckers use 'Alpha, Bravo, Charlie...' instead of letters so nothing is misheard on the radio or phone. Learn it — it makes you sound professional."],"qz":[["Why do drivers use 'Alpha, Bravo, Charlie' instead of letters?",["It's faster","To avoid confusion on the radio","It's required by law","It's a game"],1],["'Can you spell that?' is used when you...",["Don't understand a spoken word","Are hungry","Need directions","Want to sleep"],0],["What does 'copy' mean on the radio?",["I disagree","I received your message","I am lost","Call me back"],1],["'Loud and clear' means...",["The signal is bad","The message was heard well","You are shouting","The radio is broken"],1]],"sp":["Spell your first and last name using the NATO alphabet (Alpha, Bravo, Charlie...).","Ism va familiyangizni NATO radio alifbosi orqali harflab ayting."]},
{"d":4,"w":1,"wt":"Survival English & Introductions","t":"Basic Questions & Small Talk","tu":"Oddiy Savollar va Suhbat","v":[["How are you?","Qalaysiz?","How are you today? — I am fine, thanks."],["What's up?","Nima gap?","Hey, what's up? — Not much, just driving."],["Long time no see","Ko'rishmaganimizga ancha bo'ldi","Hey! Long time no see!"],["Have a safe trip","Yo'lingiz xavfsiz bo'lsin","Have a safe trip, see you next week."],["Take care","O'zingizga ehtiyot bo'ling","Take care and drive safe."],["See you later","Keyin ko'rishamiz","Alright, see you later!"],["What's new?","Nima gap, yangilik bormi?","Hey, what's new with you?"],["Not much","Unchalik emas","Not much, just another day on the road."],["I'm doing great","Ajoyibman","I'm doing great, thanks for asking!"],["How's your day going?","Kuningiz qalay o'tyapti?","How's your day going so far?"],["Same as usual","Odatdagidek","Same as usual, just driving and delivering."],["Good to see you","Sizni ko'rganimdan xursandman","Good to see you again, my friend."],["It's been a while","Ancha bo'ldi ko'rishmaganimizga","It's been a while since we last talked."],["Catch you later","Keyinroq ko'rishamiz","Alright, catch you later on the road."],["Have a good one","Kuningiz yaxshi o'tsin","Have a good one, safe travels."],["Stay safe","Xavfsiz bo'ling","Stay safe out there this week."],["Good luck","Omad tilayman","Good luck with your new route."],["No worries","Xavotir olmang","No worries, take your time."],["Sounds good","Yaxshi eshitiladi / Xo'p bo'ladi","Sounds good, I'll meet you there."],["Talk to you soon","Tez orada gaplashamiz","Talk to you soon, take care."]],"dl":[["Driver A","Hey! How are you? Long time no see!","Salom! Qalaysiz? Ko'rishmaganimizga ancha bo'ldi!"],["Driver B","I'm good, just tired. Busy week.","Yaxshiman, ozgina charchadim. Band hafta bo'ldi."],["Driver A","I understand. Where are you headed?","Tushunaman. Qayerga ketyapsiz?"],["Driver B","Chicago. You?","Chikagoga. Sizchi?"],["Driver A","Dallas. Well, take care and have a safe trip.","Dallasga. Xo'sh, o'zingizga ehtiyot bo'ling va yo'lingiz xavfsiz bo'lsin."],["Driver B","You too! See you later.","Sizga ham! Keyin ko'rishamiz."]],"g":["Small talk basics","Small talk is short, friendly conversation. Answer briefly, then ask a question back — it keeps the conversation natural: 'I'm good, how about you?'"],"qz":[["'What's up?' is a casual way to ask...",["Where do you live?","How are you / what's new?","What time is it?","Are you hungry?"],1],["Best response to 'Have a safe trip!' is:",["No thanks","Thank you, you too!","I don't drive","Goodbye forever"],1],["'Long time no see' means...",["I never saw you","I haven't seen you in a while","You look tired","See you tomorrow"],1],["'Take care' is used to...",["Say hello","Say goodbye kindly","Ask a favor","Give directions"],1]],"sp":["Practice a short small-talk exchange: greet someone, ask how they are, and say goodbye.","Qisqa suhbat mashq qiling: kimnidir salomlang, holini so'rang va xayrlashing."]},
{"d":5,"w":1,"wt":"Survival English & Introductions","rev":true,"t":"Week 1 Review — Rest Stop Check","tu":"1-hafta Takrorlash — Dam Olish Bekati Tekshiruvi","qz":[["'Nice to meet you' is said when...",["You meet someone for the first time","You say goodbye","You are angry","You need help"],0],["Phone numbers are spoken...",["As one word","Digit by digit","In Uzbek only","Never out loud"],1],["The NATO alphabet word for 'A' is:",["Apple","Alpha","Ant","Alfa-romeo"],1],["'Copy, loud and clear' means:",["I did not hear you","The message was received well","Please repeat","I am busy"],1],["'How are you?' — a natural reply is:",["I am 35 years old","I'm good, thanks. And you?","I am a driver","Yes, I am"],1],["'Take care' is closest in meaning to:",["Hello","Be careful / goodbye","I'm sorry","Wait here"],1],["Which is a polite way to ask someone to spell a word?",["Spell it now!","Can you spell that, please?","What?","Say it again louder"],1],["'Where are you from?' asks about your:",["Job","Home country","Truck","Schedule"],1]],"sp":["Call a new dispatcher: introduce yourself (name, country, job), spell your last name, and ask how they are.","Yangi dispetcherga qo'ng'iroq qiling: o'zingizni tanishtiring (ism, mamlakat, kasb), familiyangizni harflang va u kishining holini so'rang."]},
{"d":6,"w":2,"wt":"The Truck & Equipment","t":"Parts of the Truck (Tractor)","tu":"Yuk Mashinasi (Traktor) Qismlari","v":[["Engine","Dvigatel","The engine is loud when it starts."],["Cab","Kabina","I sleep in the cab at night."],["Hood","Kapot","Open the hood to check the oil."],["Mirror","Oyna (ko'zgu)","Check your mirror before you turn."],["Headlight / Taillight","Old chiroq / Orqa chiroq","Your taillight is broken."],["Fuel tank","Yoqilg'i baki","The fuel tank is almost empty."],["Exhaust pipe","Chiqindi gaz trubasi","Check the exhaust pipe for damage."],["Muffler","Shovqin so'ndirgich","The muffler is loud — it might be broken."],["Battery","Akkumulyator","The battery is under the cab."],["Radiator","Radiator (sovutish tizimi)","Check the radiator for coolant leaks."],["Air filter","Havo filtri","Replace the air filter every few months."],["Fuel filter","Yoqilg'i filtri","A dirty fuel filter can cause engine problems."],["Clutch","Sirpanchiq (kluch)","The clutch feels loose today."],["Transmission","Uzatma qutisi (transmissiya)","The transmission shifts smoothly."],["Steering wheel","Rul","Keep both hands on the steering wheel."],["Dashboard","Boshqaruv paneli (panel)","All the warning lights are on the dashboard."],["Horn","Signal (gudok)","Honk the horn to warn other drivers."],["Windshield wipers","Old oyna tozalagichlari","Turn on the wipers, it's raining."],["Bumper","Bamper","The front bumper has a small dent."],["Grille","Panjara (old qism)","Clean the grille to keep the engine cool."]],"dl":[["Mechanic","Open the hood — I need to check the engine.","Kapotni oching — dvigatelni tekshirishim kerak."],["Driver","Okay, one moment.","Xo'p, bir daqiqa."],["Mechanic","Your left mirror is loose. And check the headlight too.","Chap oynangiz bo'sh. Old chiroqni ham tekshiring."],["Driver","I saw that this morning. I will fix the mirror.","Buni bugun ertalab ko'rgandim. Oynani tuzataman."],["Mechanic","Good. And your fuel tank is low — fill it up before you leave.","Yaxshi. Yoqilg'i bakingiz kam — jo'nashdan oldin to'ldiring."]],"dl_note":"","g":["The vs no article","Use 'the' for specific parts of your own truck: 'the engine, the cab.' Use 'a/an' the first time you mention something new: 'a mechanic.'"],"qz":[["Where does the driver sleep in a truck?",["The hood","The cab","The mirror","The fuel tank"],1],["You open the ___ to check the engine.",["mirror","hood","taillight","cab"],1],["A broken light at the back of the truck is the:",["Headlight","Taillight","Mirror","Hood"],1],["What do you check before you turn?",["The fuel tank","The hood","Your mirror","The engine"],2]],"sp":["Describe 3 parts of your truck and what they are used for.","Yuk mashinangizning 3 ta qismini va ular nima uchun ishlatilishini tasvirlab bering."]},
{"d":7,"w":2,"wt":"The Truck & Equipment","t":"Parts of the Trailer","tu":"Tirkama (Pritsep) Qismlari","v":[["Trailer","Tirkama / Pritsep","The trailer is 53 feet long."],["Axle","O'q (aks)","This trailer has three axles."],["Tire","Shina / G'ildirak","Check every tire before you drive."],["Brake","Tormoz","Test the brakes before the trip."],["Landing gear","Tayanch oyoqlar (opora)","Lower the landing gear before you unhook."],["Reefer / Dry van","Sovutgichli tirkama / Yopiq tirkama","This load needs a reefer trailer."],["Container","Konteyner","We are hauling a shipping container."],["Ramp","Panjur (kirish qiyaligi)","Lower the ramp to load the cargo."],["Ratchet strap","Mahkamlash tasmasi","Tighten the ratchet strap around the load."],["Roof","Tom (tirkama tomi)","Check the trailer roof for leaks."],["Floor","Pol","The trailer floor is made of strong wood."],["Door seal","Eshik zichlagichi","A broken door seal lets water inside."],["Bulkhead","To'siq devor (bulkhead)","The bulkhead protects the cab from cargo."],["Suspension","Osma tizim (podveska)","Check the suspension before a long trip."],["Wheel well","G'ildirak nishi","Inspect the wheel well for rust."],["King pin","King-pin (ulash qismi)","The king pin connects the trailer to the truck."],["Fifth wheel","Beshinchi g'ildirak (ulagich)","Lubricate the fifth wheel regularly."],["Pintle hook","Pintle ilgagi","The pintle hook connects a second trailer."],["Nose of the trailer","Tirkama old qismi","Inspect the nose of the trailer for cracks."],["Reefer unit","Sovutgich qurilmasi","The reefer unit keeps the temperature at 34°F."]],"dl":[["Trainer","This is a dry van trailer — no refrigeration.","Bu yopiq tirkama — sovutgichsiz."],["Trainee","I see. And what is a reefer trailer?","Tushunarli. Sovutgichli tirkama nima?"],["Trainer","A reefer keeps food cold. Now, always lower the landing gear before you unhook.","Sovutgichli tirkama ovqatni sovuq saqlaydi. Har doim ajratishdan oldin tayanch oyoqlarni tushiring."],["Trainee","Okay. And I should check every tire and axle too?","Xo'p. Har bir shina va o'qni ham tekshirishim kerakmi?"],["Trainer","Yes, every time. Safety first.","Ha, har safar. Avvalo — xavfsizlik."]],"g":["Imperatives for instructions","Trainers and mechanics often give commands: 'Lower the landing gear. Check the tires.' No subject is needed — this is normal for instructions."],"qz":[["A trailer that keeps food cold is called a:",["Dry van","Reefer","Flatbed","Tanker"],1],["What should you lower before you unhook the trailer?",["The mirror","The landing gear","The headlight","The engine"],1],["A trailer with no refrigeration is a:",["Reefer","Tanker","Dry van","Lowboy"],2],["What connects the trailer to the ground when it's parked alone?",["Brakes","Landing gear","Tires","Axle"],1]],"sp":["Explain the difference between a dry van and a reefer trailer.","Yopiq tirkama (dry van) va sovutgichli tirkama (reefer) o'rtasidagi farqni tushuntiring."]},
{"d":8,"w":2,"wt":"The Truck & Equipment","t":"Tools & Equipment","tu":"Asboblar va Jihozlar","v":[["Wrench","Kalit (asbob)","Use a wrench to tighten the bolt."],["Flashlight","Fonar","Take a flashlight for the night inspection."],["Tire gauge","Shina bosimini o'lchagich","Check the pressure with a tire gauge."],["Wheel chock","G'ildirak tirgovuchi","Put a wheel chock behind the tire."],["Tarp","Bryzent","Cover the flatbed load with a tarp."],["Reflective triangle","Aks ettiruvchi uchburchak","Place the reflective triangle if you stop on the road."],["Screwdriver","Otvyortka","Use a screwdriver to fix the light cover."],["Hammer","Bolg'a","Keep a hammer in your toolbox."],["Pliers","Qisqich (plyoskogubtsy)","Use pliers to hold the small part."],["Jack","Domkrat","Use the jack to lift the truck safely."],["Jumper cables","Akkumulyator simlari","Bring jumper cables in case the battery dies."],["Duct tape","Skotch lenta (mahkam)","Duct tape can fix a small problem temporarily."],["First aid kit","Tez tibbiy yordam qutisi","Every truck must have a first aid kit."],["Fire extinguisher","Yong'in o'chirgich","Check the fire extinguisher's expiration date."],["Air hose","Havo shlangi","Connect the air hose to check the brakes."],["Work gloves","Ish qo'lqoplari","Wear work gloves during the inspection."],["Safety vest","Xavfsizlik jiketi","Put on your safety vest before you exit the cab."],["Hard hat","Qattiq shlyapa (kaska)","Wear a hard hat at the construction site."],["Bungee cord","Elastik arqon (bungee)","Use a bungee cord to secure loose items."],["Tape measure","O'lchov lentasi","Use a tape measure to check the load height."]],"dl":[["Driver","I'm getting ready for pre-trip. Do you have a flashlight?","Pre-trip uchun tayyorlanyapman. Fonaringiz bormi?"],["Coworker","Yes, here. Do you have your tire gauge and wheel chocks too?","Ha, mana. Shina bosimini o'lchagich va g'ildirak tirgovuchlaringiz ham bormi?"],["Driver","Yes, everything is in the toolbox. Thanks.","Ha, hammasi asboblar qutisida. Rahmat."],["Coworker","Don't forget the reflective triangles — you need them by law.","Aks ettiruvchi uchburchaklarni unutmang — qonun bo'yicha ular kerak."]],"g":["Countable vs uncountable tools","Most tools are countable: a wrench, two flashlights, three triangles. Use 'a/an' for one, plural -s for more than one."],"qz":[["What do you use to check tire pressure?",["Flashlight","Tire gauge","Wrench","Tarp"],1],["A wheel chock is placed:",["On the windshield","Behind the tire","In the cab","On the mirror"],1],["What covers a flatbed load to protect it?",["Tarp","Wrench","Chock","Gauge"],0],["Why do you need reflective triangles?",["To fix the engine","For safety if you stop on the road","To clean the truck","To check oil"],1]],"sp":["List 5 tools every truck driver should carry and say what each one is for.","Har bir haydovchi olib yurishi kerak bo'lgan 5 ta asbobni sanab, ularning vazifasini tushuntiring."]},
{"d":9,"w":2,"wt":"The Truck & Equipment","t":"Trailer Types & Cargo","tu":"Tirkama Turlari va Yuk","v":[["Flatbed","Platforma (ochiq tirkama)","We are hauling steel on a flatbed."],["Tanker","Sisterna","The tanker carries liquid fuel."],["Lowboy","Past platforma (og'ir yuk uchun)","A lowboy is used for heavy machinery."],["Hazmat","Xavfli yuk (hazardous material)","This load is hazmat — handle with care."],["Oversized load","Katta o'lchamdagi yuk","We need a permit for an oversized load."],["LTL (Less Than Truckload)","To'liq bo'lmagan yuk","This is an LTL shipment — multiple stops."],["Step deck","Pastki platforma (step deck)","A step deck trailer carries taller cargo."],["Double drop","Ikki bosqichli platforma","Use a double drop trailer for very tall equipment."],["Curtain-side trailer","Parda yonli tirkama","A curtain-side trailer is easy to load from the side."],["Intermodal","Intermodal (ko'p turdagi tashish)","This is an intermodal container from the port."],["Container chassis","Konteyner shassisi","The container sits on a chassis."],["Bulk trailer","Sochma yuk tirkamasi","A bulk trailer carries grain or sand."],["Livestock trailer","Chorva mol tashish tirkamasi","A livestock trailer needs ventilation."],["Car hauler","Mashina tashuvchi tirkama","A car hauler carries multiple vehicles."],["Dump trailer","Ag'darma tirkama","A dump trailer unloads by tilting up."],["Pup trailer","Kichik tirkama (pup)","We're pulling two pup trailers today."],["Freight","Yuk (tashiladigan tovar)","This freight must arrive by Friday."],["Shipment","Jo'natma","Track the shipment using the tracking number."],["Load weight","Yuk og'irligi","Confirm the load weight before departure."],["Cargo insurance","Yuk sug'urtasi","Make sure the cargo insurance is valid."]],"dl":[["Dispatcher","Your next load is a flatbed with steel beams.","Keyingi yukingiz platformada po'lat balkalar."],["Driver","Okay. Is it an oversized load?","Xo'p. Bu katta o'lchamdagi yukmi?"],["Dispatcher","Yes, you'll need a permit and escort vehicle.","Ha, sizga ruxsatnoma va kuzatuvchi mashina kerak bo'ladi."],["Driver","Understood. And is it hazmat?","Tushundim. Bu hazmatmi?"],["Dispatcher","No, just heavy steel — not hazardous.","Yo'q, faqat og'ir po'lat — xavfli emas."]],"g":["Talking about loads","Use 'hauling' or 'carrying' for cargo: 'I am hauling steel. We are carrying a hazmat load.' These are common trucking verbs."],"qz":[["Which trailer is open and flat, used for steel or machinery?",["Reefer","Flatbed","Tanker","Dry van"],1],["A tanker trailer usually carries:",["Boxes","Liquid","Cars","Animals"],1],["'Hazmat' means the cargo is:",["Heavy","Hazardous/dangerous","Fresh","Expensive"],1],["An oversized load usually requires a:",["Tarp","Permit and escort","Reefer unit","Wheel chock"],1]],"sp":["Describe what kind of trailer you would use for: steel, food, gasoline, and heavy machinery.","Quyidagilar uchun qanday tirkama ishlatilishini tasvirlang: po'lat, oziq-ovqat, benzin va og'ir texnika."]},
{"d":10,"w":2,"wt":"The Truck & Equipment","rev":true,"t":"Week 2 Review — Equipment Check","tu":"2-hafta Takrorlash — Jihozlarni Tekshirish","qz":[["Where does a driver sleep?",["The trailer","The cab","The hood","The dock"],1],["Which part connects the trailer to the ground when parked?",["Axle","Landing gear","Tire","Brake"],1],["A reefer trailer is used for:",["Steel","Refrigerated goods","Liquids","Machinery"],1],["What tool checks tire pressure?",["Wrench","Flashlight","Tire gauge","Tarp"],2],["What do you place if you stop on the roadside?",["A tarp","A reflective triangle","A wheel chock","A wrench"],1],["A tanker trailer carries:",["Boxes","Liquid","Animals","Furniture"],1],["'Hazmat' cargo is:",["Fragile","Hazardous","Frozen","Oversized only"],1],["What do you need for an oversized load?",["A reefer unit","A permit","A tarp","A tire gauge"],1]],"sp":["Give a mechanic a full walk-around description of your truck and trailer, naming at least 8 parts.","Mexanikka yuk mashinangiz va tirkamangiz haqida to'liq tushuntirish bering, kamida 8 ta qismni nomlab."]},
{"d":11,"w":3,"wt":"Pre-Trip Inspection & Road Rules","t":"Pre-Trip Inspection Basics","tu":"Pre-Trip Tekshiruv Asoslari","v":[["Inspect","Tekshirmoq","Inspect the brakes before every trip."],["Leak","Oqish (suyuqlik)","There is an oil leak under the engine."],["Worn","Yeyilgan / Eskirgan","This tire is worn — replace it."],["Crack","Yoriq","I found a crack in the windshield."],["Secure","Mahkam / Bog'langan","Make sure the load is secure."],["Loose / Tight","Bo'sh / Mahkam","This bolt is loose — tighten it."],["Check the fluid","Suyuqlikni tekshirmoq","Check the fluid levels before you drive."],["Test the lights","Chiroqlarni tekshirmoq","Test the lights — turn signals, brakes, and headlights."],["Inspect the coupling","Ulanishni tekshirmoq","Inspect the coupling between the truck and trailer."],["Look for rust","Zanglarni qidirmoq","Look for rust on the frame and undercarriage."],["Tire tread","Shina protektori","Check the tire tread depth with a gauge."],["Brake pads","Tormoz kolodkalari","The brake pads are worn and need replacing."],["Air pressure","Havo bosimi","Check the air pressure in all tires."],["Fifth wheel lock","Beshinchi g'ildirak qulfi","Make sure the fifth wheel lock is engaged."],["Reflectors","Aks ettirgichlar","Clean the reflectors so they are visible at night."],["Emergency kit","Favqulodda holat to'plami","Keep an emergency kit behind the seat."],["Fan belt","Ventilyator kamari","Listen for a squealing fan belt."],["Hose","Shlang","Check every hose for cracks or leaks."],["Coupling device","Ulash qurilmasi","The coupling device must be secure and locked."],["Undercarriage","Pastki qism (shassidan pastda)","Inspect the undercarriage for damage."]],"dl":[["Trainer","Let's do the pre-trip inspection. Check the tires first.","Pre-trip tekshiruvni boshlaylik. Avval shinalarni tekshiring."],["Trainee","This tire looks worn. Should I report it?","Bu shina yeyilganga o'xshaydi. Buni xabar qilishim kerakmi?"],["Trainer","Yes, always report a worn tire or a leak. Now check if everything is secure.","Ha, doim yeyilgan shina yoki oqishni xabar qiling. Endi hammasi mahkamligini tekshiring."],["Trainee","This bolt is loose. I will tighten it.","Bu bolt bo'sh. Men uni mahkamlayman."],["Trainer","Good catch. A good inspection prevents accidents.","Yaxshi payqadingiz. Yaxshi tekshiruv baxtsiz hodisalarning oldini oladi."]],"g":["Past tense of find","'I found a crack' — 'find' becomes 'found' in the past. Use this to report something you discovered: I found a leak. I found a problem."],"qz":[["What should you do before every trip?",["Sleep","Inspect the truck","Call your family","Eat lunch"],1],["A tire that is old and thin is:",["Secure","Tight","Worn","New"],2],["If a bolt is not tight, it is:",["Loose","Secure","Worn","Cracked"],0],["If you find a fluid leaking from the engine, you should:",["Ignore it","Report it","Drive faster","Wait a week"],1]],"sp":["Describe how you do a pre-trip inspection, step by step.","Pre-trip tekshiruvni qadam-baqadam qanday bajarishingizni tasvirlab bering."]},
{"d":12,"w":3,"wt":"Pre-Trip Inspection & Road Rules","t":"Road Signs","tu":"Yo'l Belgilari","v":[["Stop sign","To'xtash belgisi","Stop completely at the stop sign."],["Yield","Yo'l bering","Yield to oncoming traffic."],["No trucks","Yuk mashinalariga taqiq","This road has a 'No Trucks' sign."],["Weight limit","Og'irlik chegarasi","The bridge has a weight limit of 20 tons."],["Low clearance","Past balandlik chegarasi","Watch for low clearance under bridges."],["Detour","Aylanma yo'l","There is a detour ahead due to construction."],["Speed bump","Tezlikni pasaytiruvchi to'siq","Slow down for the speed bump ahead."],["Railroad crossing","Temir yo'l kesishmasi","Stop and look both ways at the railroad crossing."],["Pedestrian crossing","Piyodalar o'tish joyi","Slow down near a pedestrian crossing."],["Curve ahead","Oldinda burilish","Slow down, there's a sharp curve ahead."],["Steep grade","Tik qiya yo'l","Use a lower gear on a steep grade."],["Runaway truck ramp","Boshqarilmaydigan mashina uchun rampa","Use the runaway truck ramp if your brakes fail."],["Truck route","Yuk mashinalari yo'li","Follow the truck route through the city."],["No U-turn","Orqaga burilish taqiqlangan","This intersection has a 'No U-turn' sign."],["Divided highway","Ajratilgan avtomagistral","We are driving on a divided highway now."],["Two-way traffic","Ikki tomonlama harakat","Be careful, this is two-way traffic."],["Keep right","O'ngda yuring","Keep right except to pass."],["Do not enter","Kirish taqiqlangan","That road has a 'Do Not Enter' sign."],["Wrong way","Noto'g'ri yo'nalish","Turn around, this is the wrong way."],["Merge sign","Qo'shilish belgisi","Watch for the merge sign near the on-ramp."]],"dl":[["Driver A","Did you see the low clearance sign back there?","Orqada past balandlik belgisini ko'rdingizmi?"],["Driver B","Yes, 12 feet 6 inches. My trailer is fine.","Ha, 12 fut 6 dyuym. Mening tirkamam mos keladi."],["Driver A","There's also a detour up ahead — construction on the bridge.","Oldinda aylanma yo'l ham bor — ko'prikda qurilish ketyapti."],["Driver B","Thanks for the warning. I'll follow the detour signs.","Ogohlantirganingiz uchun rahmat. Aylanma yo'l belgilariga amal qilaman."]],"g":["Modal 'must' for signs","Road signs often mean 'must': A stop sign means you must stop. A yield sign means you must give way."],"qz":[["A 'Yield' sign means:",["Stop completely","Give way to other traffic","Speed up","No trucks allowed"],1],["'Low clearance' warns drivers about:",["Weight limits","Height limits under bridges","Speed limits","No parking"],1],["A 'detour' is:",["A shortcut","An alternate route around a closed road","A gas station","A weigh station"],1],["A weight limit sign on a bridge tells you:",["The bridge is closed","The maximum weight allowed","The speed limit","The toll price"],1]],"sp":["Explain what you should do when you see a 'Yield', a 'Low Clearance', and a 'Detour' sign.","'Yield', 'Low Clearance' va 'Detour' belgilarini ko'rganda nima qilishingiz kerakligini tushuntiring."]},
{"d":13,"w":3,"wt":"Pre-Trip Inspection & Road Rules","t":"Traffic Laws & Speed","tu":"Yo'l Harakati Qoidalari va Tezlik","v":[["Speed limit","Tezlik chegarasi","The speed limit is 65 miles per hour."],["School zone","Maktab hududi","Slow down — this is a school zone."],["Construction zone","Qurilish hududi","Fines double in a construction zone."],["Right of way","Ustunlik huquqi","The other car has the right of way."],["Lane","Yo'lak (polosa)","Stay in the right lane, trucks only."],["No passing","O'tib ketish taqiqlangan","This is a no-passing zone."],["Tailgating","Yaqin ergashib yurish","Tailgating another truck is dangerous."],["Blind spot","Ko'rinmas hudud","Motorcycles often hide in your blind spot."],["Following distance","Orqadan kuzatish masofasi","Keep a safe following distance in rain."],["Turn signal","Burilish signali","Use your turn signal before changing lanes."],["Seatbelt law","Xavfsizlik kamari qonuni","The seatbelt law applies to all drivers."],["Cell phone law","Telefon qonuni","Hands-free devices are required by the cell phone law."],["Reckless driving","Beparvo haydash","Reckless driving can lead to a big fine."],["Move over law","Chetga o'tish qonuni","The move over law protects roadside workers."],["Work zone","Ish zonasi","Slow down in every work zone."],["Fine amount","Jarima miqdori","The fine amount depends on your speed."],["Yield to pedestrians","Piyodalarga yo'l bermoq","Always yield to pedestrians at crosswalks."],["Double fine zone","Ikki barobar jarima zonasi","This highway has a double fine zone."],["License points","Guvohnoma ballari","Too many license points can suspend your CDL."],["Suspension (license)","Guvohnomani to'xtatish","A serious violation can lead to license suspension."]],"dl":[["Trainer","Remember, fines double in a construction zone.","Esda tuting, qurilish hududida jarima ikki barobar bo'ladi."],["Trainee","Got it. And what about school zones?","Tushundim. Maktab hududlarida-chi?"],["Trainer","Same — always slow down. Also, stay in the right lane unless you're passing.","Xuddi shunday — doim sekinlashing. Shuningdek, o'tib ketmasangiz, o'ng yo'lakda yuring."],["Trainee","What if there's a 'No Passing' sign?","Agar 'O'tish taqiqlangan' belgisi bo'lsa-chi?"],["Trainer","Then stay behind the vehicle until the zone ends.","U holda hudud tugaguncha mashinaning orqasida qoling."]],"g":["Comparatives with speed","Say '65 miles per hour' or '65 mph.' Use 'slow down' (verb) and 'speed limit' (noun): 'Slow down, the speed limit here is 45.'"],"qz":[["Fines in a construction zone are usually:",["The same","Doubled","Cancelled","Lower"],1],["Trucks usually should stay in the:",["Left lane","Right lane","Middle lane","Any lane"],1],["'Right of way' means:",["You must stop","Another vehicle can go first","You can speed up","It's a one-way road"],1],["A 'No Passing' sign means:",["You must exit","You cannot pass another vehicle here","You must pay a toll","Speed limit ends"],1]],"sp":["Explain 3 traffic rules a new truck driver must always remember.","Yangi haydovchi doim yodda tutishi kerak bo'lgan 3 ta yo'l qoidasini tushuntiring."]},
{"d":14,"w":3,"wt":"Pre-Trip Inspection & Road Rules","t":"Giving & Following Directions","tu":"Yo'l Ko'rsatish va Unga Amal Qilish","v":[["Turn left / right","Chapga / O'ngga buriling","Turn left at the next light."],["Go straight","To'g'ri yuring","Go straight for two miles."],["Merge onto","...ga qo'shiling (kirib boring)","Merge onto Interstate 80 East."],["Exit number","Chiqish raqami","Take exit number 42."],["Mile marker","Milya belgisi","The truck stop is at mile marker 210."],["North / South / East / West","Shimol / Janub / Sharq / G'arb","Head north on Highway 35."],["Left lane","Chap yo'lak","Use the left lane only to pass."],["Right lane","O'ng yo'lak","Stay in the right lane as a truck."],["Fork in the road","Yo'lning ayrilishi","Take the left path at the fork in the road."],["Intersection","Chorraha","Slow down before every intersection."],["Traffic light","Svetofor","Stop at the red traffic light."],["Crosswalk","Piyodalar o'tish joyi","Wait for pedestrians at the crosswalk."],["GPS coordinates","GPS koordinatalari","Send me the GPS coordinates of the site."],["Landmark","Mo'ljal (belgi)","Turn right after the gas station landmark."],["Straight ahead","To'g'ri oldinda","The warehouse is straight ahead."],["Behind you","Orqangizda","The truck stop is behind you now."],["Next to","Yonida","The dock is next to the main office."],["Across from","Qarama-qarshisida","Park across from the fuel island."],["Around the corner","Burchak orqasida","The office is around the corner."],["U-turn","Orqaga burilish","Make a U-turn at the next light."]],"dl":[["Driver","Excuse me, how do I get to the truck stop from here?","Kechirasiz, bu yerdan yuk mashinalari to'xtash joyiga qanday boraman?"],["Attendant","Go straight for two miles, then merge onto Highway 20 East.","Ikki milya to'g'ri yuring, keyin 20-shosseга sharqqa qo'shiling."],["Driver","Okay, straight, then merge east. What exit?","Xo'p, to'g'ri, keyin sharqqa qo'shilaman. Qaysi chiqish?"],["Attendant","Take exit 15. It's right at mile marker 88.","15-chiqishdan chiqing. U 88-milya belgisida joylashgan."],["Driver","Got it, thank you very much!","Tushundim, katta rahmat!"]],"g":["Prepositions of direction","'Onto' = joining a road (merge onto). 'At' = a point (turn at the light, exit at mile marker 88). 'For' = distance (go straight for 2 miles)."],"qz":[["'Merge onto the highway' means:",["Exit the highway","Join the highway","Stop on the highway","Park on the highway"],1],["A 'mile marker' tells you:",["The speed limit","Your exact location on the road","The weather","The weight limit"],1],["'Go straight for two miles' means:",["Turn now","Continue without turning for 2 miles","Stop in 2 miles","Turn around"],1],["If someone says 'take exit 42', you should:",["Continue straight","Turn around","Leave the highway at exit 42","Merge left"],2]],"sp":["Give directions from the truck stop to the highway, using at least 4 direction words.","Yuk mashinalari to'xtash joyidan shosseygacha bo'lgan yo'lni, kamida 4 ta yo'nalish so'zidan foydalanib tushuntiring."]},
{"d":15,"w":3,"wt":"Pre-Trip Inspection & Road Rules","rev":true,"t":"Week 3 Review — Road Rules Checkpoint","tu":"3-hafta Takrorlash — Yo'l Qoidalari Nazorati","qz":[["Before every trip, a driver must:",["Wash the truck","Inspect the truck","Call dispatch only","Sleep 8 hours"],1],["A 'Yield' sign means you must:",["Stop completely","Give way to other traffic","Honk your horn","Turn around"],1],["Trucks usually drive in the:",["Left lane","Right lane","Center lane","Shoulder"],1],["'Low clearance' refers to:",["Weight","Height under a bridge","Speed","Width"],1],["Fines are often doubled in a:",["Rest area","Construction zone","Truck stop","Parking lot"],1],["A worn tire should be:",["Ignored","Reported","Driven on longer","Painted"],1],["'Merge onto the interstate' means to:",["Exit","Join the road","Stop","Reverse"],1],["A mile marker shows your:",["Weight","Exact location","Fuel level","Speed"],1]],"sp":["You are training a new driver. Explain the pre-trip inspection and 3 important road signs.","Siz yangi haydovchini o'qityapsiz. Pre-trip tekshiruvni va 3 ta muhim yo'l belgisini tushuntiring."]},
{"d":16,"w":4,"wt":"Driving & Navigation","t":"Highway & Interstate Terms","tu":"Avtomagistral va Shtatlararo Yo'l Atamalari","v":[["Interstate","Shtatlararo avtomagistral","We are driving on Interstate 40."],["On-ramp / Off-ramp","Kirish / Chiqish rampasi","Use the on-ramp to enter the highway."],["Shoulder","Yo'l chekkasi (bankett)","Pull onto the shoulder if you have a problem."],["Rest area","Dam olish maydoni","There's a rest area in 10 miles."],["Toll road","Pullik yo'l","This is a toll road — keep cash ready."],["Rush hour","Tirbandlik soati","Avoid the city during rush hour."],["Beltway","Aylanma yo'l (shahar atrofida)","Take the beltway around the city."],["Overpass","Yuqori ko'prik (estakada)","Watch your height under the overpass."],["Underpass","Pastki o'tish joyi","This underpass has a low clearance."],["Median","O'rta chiziq (ajratuvchi)","Do not cross the median."],["Guardrail","Himoya panjarasi","A guardrail runs along the mountain road."],["Truck lane","Yuk mashinalari yo'lagi","Stay in the truck lane on this stretch."],["Weigh station ahead","Oldinda tarozi bekati","There's a sign for a weigh station ahead."],["Speed trap","Tezlik pistirmasi (nazorat)","Watch for a speed trap near the town."],["Traffic camera","Trafik kamerasi","A traffic camera is at this intersection."],["Construction cone","Qurilish konusi","Slow down around the construction cones."],["Lane closure","Yo'lak yopilishi","There's a lane closure two miles ahead."],["Merge point","Qo'shilish nuqtasi","Slow down before the merge point."],["Bottleneck","Tiqilinch joyi (torayish)","There's a bottleneck near the bridge."],["Carpool lane","Hamkorlikda yo'lak","Trucks cannot use the carpool lane."]],"dl":[["Driver A","Are we taking the toll road or the free route?","Pullik yo'ldan boramizmi yoki bepul yo'ldanmi?"],["Driver B","The toll road — it's faster and we avoid rush hour in the city.","Pullik yo'ldan — u tezroq va shahardagi tirbandlik soatidan qochamiz."],["Driver A","Good idea. Is there a rest area before the on-ramp?","Yaxshi fikr. Kirish rampasidan oldin dam olish maydoni bormi?"],["Driver B","Yes, right before it. Let's stop there first.","Ha, undan oldin. Avval o'sha yerda to'xtaylik."]],"g":["Talking about routes","Use 'take' for choosing a road: 'take the toll road, take exit 12.' Use 'avoid' for what you don't want: 'avoid rush hour.'"],"qz":[["The 'shoulder' of the highway is used for:",["Fast driving","Emergency stops","Parking overnight","Passing other trucks"],1],["A 'toll road' requires you to:",["Pay money","Drive slowly","Stop every mile","Show your CDL"],0],["'Rush hour' means:",["Early morning only","A time with heavy traffic","No traffic at all","A holiday"],1],["You enter a highway using the:",["Off-ramp","Shoulder","On-ramp","Rest area"],2]],"sp":["Describe your ideal route: which roads you'd take and why, using at least 4 vocabulary words from today.","Bugungi mavzudan kamida 4 ta so'zdan foydalanib, o'zingiz tanlagan ideal marshrutni tasvirlab bering."]},
{"d":17,"w":4,"wt":"Driving & Navigation","t":"GPS & Route Planning","tu":"GPS va Marshrut Rejalashtirish","v":[["Route","Marshrut","Follow this route to avoid traffic."],["Detour","Aylanma yo'l","GPS suggests a detour ahead."],["ETA (Estimated Time of Arrival)","Taxminiy yetib borish vaqti","My ETA is 6 PM."],["Mileage","Bosib o'tilgan masofa","Total mileage for this trip is 850 miles."],["Backhaul","Qaytish yuki","We have a backhaul from Denver."],["Deadhead","Yuksiz haydash","I'm deadheading back to the terminal."],["Waypoint","Marshrut nuqtasi","Add a waypoint for the fuel stop."],["Pickup location","Yuklab olish joyi","Confirm the pickup location with dispatch."],["Delivery location","Yetkazib berish joyi","The delivery location is 300 miles away."],["Trip sheet","Safar varag'i","Fill out your trip sheet at the end of the day."],["Fuel stop","Yoqilg'i to'xtash joyi","Plan a fuel stop before the mountains."],["Alternate route","Muqobil yo'l","Take the alternate route to avoid traffic."],["Shortest route","Eng qisqa yo'l","The GPS shows the shortest route."],["Fastest route","Eng tez yo'l","Take the fastest route to save time."],["Traffic delay","Tirbandlik kechikishi","There's a traffic delay of 30 minutes."],["Road closure","Yo'l yopilishi","There's a road closure ahead due to flooding."],["Live traffic","Jonli trafik ma'lumoti","Check live traffic before you leave."],["Navigation app","Navigatsiya ilovasi","Use a trucking navigation app, not a regular GPS."],["Reroute","Marshrutni o'zgartirmoq","Dispatch asked me to reroute around the storm."],["Trip plan","Safar rejasi","Send dispatch your trip plan for approval."]],"dl":[["Dispatcher","What's your ETA to the delivery?","Yetkazib berish joyiga taxminiy qachon yetib borasiz?"],["Driver","My ETA is 3 PM. Total mileage today is about 400 miles.","Taxminan soat 3 da. Bugungi umumiy masofa taxminan 400 milya."],["Dispatcher","Good. After delivery, you have a backhaul from the same city.","Yaxshi. Yetkazgandan so'ng, o'sha shahardan qaytish yuki bor."],["Driver","Great, no deadheading then. What time should I pick it up?","Ajoyib, yuksiz haydashga to'g'ri kelmaydi. Qachon olib ketishim kerak?"],["Dispatcher","5 PM. I'll send the address.","Soat 5 da. Manzilni yuboraman."]],"g":["Present continuous for near-future plans","'I'm deadheading back' uses present continuous to describe a planned near-future action, common in trucking talk about routes and schedules."],"qz":[["'ETA' stands for:",["Estimated Time of Arrival","Every Ten Accidents","Extra Time Allowed","Exit Time Ahead"],0],["'Deadhead' means driving:",["With a full load","Empty, without cargo","Very fast","Backwards"],1],["A 'backhaul' is:",["A load picked up on the return trip","A broken trailer","A type of fuel","A rest stop"],0],["'Mileage' refers to:",["Fuel price","Distance traveled","Weight of cargo","Number of stops"],1]],"sp":["Tell dispatch your ETA, your mileage for the day, and whether you have a backhaul.","Dispetcherga taxminiy yetib borish vaqtingizni, kunlik masofangizni va qaytish yuki bor-yo'qligini ayting."]},
{"d":18,"w":4,"wt":"Driving & Navigation","t":"Weather & Road Conditions","tu":"Ob-havo va Yo'l Sharoitlari","v":[["Icy road","Muzlagan yo'l","Slow down, the road is icy."],["Fog","Tuman","Use fog lights when visibility is low."],["Heavy rain","Kuchli yomg'ir","Heavy rain is expected this afternoon."],["Black ice","Ko'rinmas muz","Watch for black ice on bridges."],["Visibility","Ko'rinish masofasi","Visibility is very low in this fog."],["Chain up","Zanjir taqmoq (g'ildirakka)","You must chain up in the mountains."],["Thunderstorm","Momaqaldiroqli bo'ron","A thunderstorm is expected this evening."],["Hail","Do'l","Pull over if there is heavy hail."],["Tornado warning","Tornado ogohlantirishi","There's a tornado warning in this county."],["Flood","Suv toshqini","The road is closed because of a flood."],["High wind advisory","Kuchli shamol ogohlantirishi","There's a high wind advisory for high-profile trucks."],["Hydroplaning","Suzib ketish (hydroplaning)","Slow down to avoid hydroplaning in heavy rain."],["Frost","Qirov","Watch for frost on the road early in the morning."],["Sleet","Qorli yomg'ir (aralash)","Sleet is making the road slippery."],["Whiteout","Oq bo'ron (qor tufayli ko'rinmaslik)","Pull over safely during a whiteout."],["Heat advisory","Issiqlik ogohlantirishi","There's a heat advisory — check your tires often."],["Storm front","Bo'ron old chegarasi","A storm front is moving in from the west."],["Weather alert","Ob-havo ogohlantirishi","I got a weather alert on my phone."],["Chain law","Zanjir qonuni","The chain law is in effect in the mountains."],["Road condition report","Yo'l holati hisoboti","Check the road condition report before driving."]],"dl":[["Dispatcher","There's a winter storm warning on your route.","Sizning marshrutingizda qishki bo'ron ogohlantirishi bor."],["Driver","Thanks for the warning. Should I chain up now?","Ogohlantirganingiz uchun rahmat. Hozir zanjir taqishim kerakmi?"],["Dispatcher","Yes, chain up before the mountain pass. Watch for black ice.","Ha, tog' dovonidan oldin zanjir taqing. Ko'rinmas muzga ehtiyot bo'ling."],["Driver","Understood. Visibility is already low from the fog.","Tushundim. Tuman tufayli ko'rinish allaqachon past."],["Dispatcher","Slow down and use your hazard lights if needed.","Sekinlashing va kerak bo'lsa avariya chiroqlaridan foydalaning."]],"g":["Weather + advice","Use 'should' for safety advice about weather: 'You should chain up. You should slow down. You should avoid black ice.'"],"qz":[["'Black ice' is dangerous because it is:",["Very thick","Hard to see on the road","Only in summer","Colorful"],1],["When visibility is low, you should:",["Speed up","Use fog lights and slow down","Turn off headlights","Stop the engine"],1],["'Chain up' means to:",["Lock the truck","Put chains on the tires for snow/ice","Connect the trailer","Call dispatch"],1],["Heavy rain reduces your:",["Fuel","Visibility and traction","Weight limit","Mileage"],1]],"sp":["Explain what a driver should do when facing icy roads, fog, and heavy rain.","Haydovchi muzlagan yo'l, tuman va kuchli yomg'irga duch kelganda nima qilishi kerakligini tushuntiring."]},
{"d":19,"w":4,"wt":"Driving & Navigation","t":"Parking & Truck Stops","tu":"To'xtash Joylari va Yuk Mashinalari Bekatlari","v":[["Truck stop","Yuk mashinalari to'xtash bekati","Let's stop at the next truck stop."],["Parking spot","Turargoh joyi","There are no parking spots available."],["Overnight parking","Tungi to'xtash","This lot allows overnight parking."],["No parking","To'xtash taqiqlangan","This area has a 'No Parking' sign."],["Full lot","To'la turargoh","Sorry, the lot is full tonight."],["Idle","Bo'sh ishlash (dvigatel)","Don't idle the engine too long — save fuel."],["Reserved parking","Band qilingan turargoh","This spot is reserved parking for members."],["Pull-through spot","O'tib ketadigan joy","A pull-through spot is easier to park in."],["Back-in spot","Orqasi bilan kiriladigan joy","I need to back into a back-in spot."],["Idle reduction area","Dvigatel o'chirilgan hudud","Park in the idle reduction area to save fuel."],["Truck wash","Yuk mashinasi yuvish joyi","Let's stop at the truck wash before the delivery."],["Scale house","Tarozi uyi","Report to the scale house when you arrive."],["Security guard","Xavfsizlik xodimi","Ask the security guard where to park."],["Gate code","Darvoza kodi","Enter the gate code to access the lot."],["Parking permit","To'xtash ruxsatnomasi","You need a parking permit for this lot."],["Overflow lot","Qo'shimcha turargoh","Use the overflow lot if the main lot is full."],["Time limit","Vaqt chegarasi","There's a 2-hour time limit in this spot."],["Guard shack","Qorovul kulbasi","Check in at the guard shack first."],["Lot attendant","Turargoh xodimi","Ask the lot attendant for directions."],["No overnight parking","Tunda to'xtash taqiqlangan","This area has a 'No Overnight Parking' sign."]],"dl":[["Driver","Do you have any parking spots left tonight?","Bugun kechqurun bo'sh turargoh joyi bormi?"],["Attendant","Let me check... I'm sorry, the lot is full.","Tekshirib ko'ray... Kechirasiz, turargoh to'la."],["Driver","Is overnight parking allowed on the street nearby?","Yaqin atrofdagi ko'chada tungi to'xtash ruxsat etilganmi?"],["Attendant","No, there's a 'No Parking' sign there. Try the truck stop 5 miles north.","Yo'q, u yerda 'To'xtash taqiqlangan' belgisi bor. Shimolda 5 milya narida yuk mashinalari bekatini sinab ko'ring."],["Driver","Thanks, I'll head there now.","Rahmat, hozir o'sha yerga boraman."]],"g":["Polite requests","'Do you have any...?' is a polite way to ask about availability: 'Do you have any parking spots? Do you have any showers available?'"],"qz":[["If a lot is 'full', it means:",["It's closed","There are no more spaces","It's free","It's under construction"],1],["'Overnight parking' means parking:",["For one hour","All night","Only during the day","At a weigh station"],1],["Why should you avoid idling your engine too long?",["It's illegal everywhere","It wastes fuel","It's too quiet","It damages the GPS"],1],["A 'No Parking' sign means you should:",["Park anyway","Not park there","Park only at night","Ask a police officer"],1]],"sp":["Call a truck stop and ask if they have overnight parking and showers available.","Yuk mashinalari bekatiga qo'ng'iroq qilib, tungi to'xtash joyi va dush borligini so'rang."]},
{"d":20,"w":4,"wt":"Driving & Navigation","rev":true,"t":"Week 4 Review — Navigation Test","tu":"4-hafta Takrorlash — Navigatsiya Sinovi","qz":[["The shoulder of the highway is used for:",["Passing","Emergency stops","Sleeping","Fueling"],1],["'ETA' means:",["Extra Toll Amount","Estimated Time of Arrival","Every Ten Axles","Exit Toll Area"],1],["'Deadhead' means driving:",["With a heavy load","Empty","In reverse","At night only"],1],["Black ice is dangerous because it's:",["Loud","Hard to see","Only found in tunnels","Warm"],1],["'Chain up' is done because of:",["Heavy rain","Snow and ice","Hot weather","Fog only"],1],["A 'full lot' at a truck stop means:",["Free parking","No available spaces","Closed for cleaning","Fuel is free"],1],["You should not idle your engine too long because it:",["Is illegal in all states","Wastes fuel","Damages tires","Stops the GPS"],1],["A 'backhaul' helps a driver avoid:",["Rush hour","Deadheading","Rest areas","Weigh stations"],1]],"sp":["Plan a route out loud: mention the highway, an ETA, weather to watch for, and where you'll park for the night.","Marshrutni ovoz chiqarib rejalashtiring: shossени, taxminiy yetib borish vaqtini, ehtiyot bo'lish kerak bo'lgan ob-havoni va kechasi qayerda to'xtashingizni ayting."]},
{"d":21,"w":5,"wt":"Hours of Service & Logbook","t":"ELD & Logbook Basics","tu":"ELD va Jurnal Asoslari","v":[["ELD (Electronic Logging Device)","Elektron jurnal qurilmasi","Every truck must have a working ELD."],["Log in / Log out","Kirish / Chiqish (tizimga)","Log in to the ELD before you start driving."],["Duty status","Vazifa holati","Change your duty status to 'driving.'"],["On duty / Off duty","Xizmatda / Xizmatdan tashqari","I am off duty until 6 AM tomorrow."],["Sleeper berth","Uxlash bo'limi (kabinada)","I'm taking 8 hours in the sleeper berth."],["Driving time","Haydash vaqti","You have 3 hours of driving time left."],["Personal conveyance","Shaxsiy foydalanish (ELD holati)","I'm using personal conveyance to drive to the hotel."],["Yard move","Hovli harakati","Set your status to yard move inside the terminal."],["Co-driver","Hamkasb haydovchi","My co-driver is sleeping in the berth now."],["Team driving","Jamoaviy haydash","Team driving allows the truck to run longer."],["Odometer reading","Spidometr ko'rsatkichi","Record the odometer reading at the start of your shift."],["Engine hours","Dvigatel soatlari","Check the engine hours before maintenance."],["Data transfer","Ma'lumot uzatish","The ELD supports data transfer to inspectors."],["ELD provider","ELD ta'minotchisi","Contact your ELD provider for support."],["Malfunction indicator","Nosozlik ko'rsatkichi","The malfunction indicator is flashing."],["Diagnostic event","Diagnostika hodisasi","A diagnostic event was recorded this morning."],["Unidentified driving","Egasi noma'lum haydash vaqti","Claim any unidentified driving time that is yours."],["Duty status change","Vazifa holati o'zgarishi","Make a duty status change before you start driving."],["Annotation","Izoh (yozib qo'yish)","Add an annotation to explain the edit."],["Driver ID","Haydovchi identifikatori","Log in with your driver ID every shift."]],"dl":[["Trainer","First, log in to the ELD with your driver ID.","Avval haydovchi ID'ingiz bilan ELD'ga kiring."],["Trainee","Okay. How do I change my duty status?","Xo'p. Vazifa holatimni qanday o'zgartiraman?"],["Trainer","Tap here — choose 'on duty', 'driving', 'sleeper berth', or 'off duty'.","Bu yerni bosing — 'on duty', 'driving', 'sleeper berth' yoki 'off duty'ni tanlang."],["Trainee","And it tracks my driving time automatically?","Va u haydash vaqtimni avtomatik kuzatib boradimi?"],["Trainer","Yes, it's automatic. Always log out correctly at the end of your shift.","Ha, avtomatik. Smena oxirida har doim to'g'ri chiqing."]],"g":["Compound nouns in trucking","English trucking terms often combine two words: 'duty status', 'sleeper berth', 'driving time'. Learn them as full phrases, not single words."],"qz":[["ELD stands for:",["Extra Load Device","Electronic Logging Device","Engine Light Display","Empty Load Detector"],1],["'Off duty' means:",["Actively driving","Not working","On a break for lunch only","Fueling the truck"],1],["Where do you rest during mandatory breaks?",["The cab floor","The sleeper berth","The trailer","The dock"],1],["The ELD automatically tracks your:",["Fuel price","Driving time","Weight","Route only"],1]],"sp":["Explain the four duty statuses on an ELD: on duty, off duty, driving, sleeper berth.","ELD'dagi to'rtta vazifa holatini tushuntiring: on duty, off duty, driving, sleeper berth."]},
{"d":22,"w":5,"wt":"Hours of Service & Logbook","t":"Hours of Service (HOS) Rules","tu":"Xizmat Soatlari (HOS) Qoidalari","v":[["11-hour rule","11 soatlik qoida","The 11-hour rule limits your driving time."],["14-hour window","14 soatlik oyna","You must finish driving within the 14-hour window."],["30-minute break","30 daqiqalik tanaffus","Take your 30-minute break after 8 hours."],["70-hour rule","70 soatlik qoida","Don't exceed the 70-hour rule in 8 days."],["Reset","Qayta boshlash (dam olish)","Take a 34-hour reset before your next week."],["Violation","Qoidabuzarlik","A HOS violation can result in a fine."],["Adverse driving conditions","Noqulay haydash sharoiti","You get extra time in adverse driving conditions."],["Short-haul exception","Qisqa masofa istisnosi","Local drivers may use the short-haul exception."],["Split sleeper berth","Bo'lingan uxlash vaqti","A split sleeper berth lets you divide your rest."],["8/2 split","8/2 bo'linishi","I used an 8/2 split last night."],["7/3 split","7/3 bo'linishi","Try a 7/3 split if you need flexibility."],["Restart","Qayta boshlash","Take a 34-hour restart this weekend."],["Cycle","Sikl (ish davri)","You are on a 70-hour, 8-day cycle."],["Off-duty time","Xizmatdan tashqari vaqt","Log your off-duty time correctly."],["On-duty not driving","Xizmatda, lekin haydamayapti","Loading time counts as on-duty not driving."],["Yard time","Hovlida bo'lgan vaqt","Yard time should be logged as on duty."],["Consecutive days","Ketma-ket kunlar","You can work up to 8 consecutive days."],["Weekly limit","Haftalik chegara","Don't exceed your weekly hour limit."],["Recap hours","Qaytarilgan soatlar","Check your recap hours before the next trip."],["Exception log","Istisno jurnali","Note any exception in your log with a comment."]],"dl":[["Driver","How many hours can I drive today?","Bugun necha soat hайdashim mumkin?"],["Dispatcher","You have 11 hours of driving left within your 14-hour window.","14 soatlik oynangiz ichida 11 soat haydash vaqtingiz qoldi."],["Driver","Got it. And I need my 30-minute break after 8 hours, right?","Tushundim. Va menga 8 soatdan keyin 30 daqiqalik tanaffus kerak, to'g'rimi?"],["Dispatcher","Correct. Also, don't forget the 70-hour rule over 8 days.","To'g'ri. Shuningdek, 8 kun ichida 70 soatlik qoidani unutmang."],["Driver","I'll plan a 34-hour reset this weekend.","Men bu hafta oxirida 34 soatlik reset qilaman."]],"g":["Modal 'must not / cannot' for rules","HOS rules use strong modals: 'You must not exceed 11 hours. You cannot drive after 14 hours.' These express legal limits."],"qz":[["The 11-hour rule limits your:",["Rest time","Maximum driving time","Fuel usage","Parking time"],1],["You must take a 30-minute break after how many hours of driving?",["4 hours","8 hours","11 hours","14 hours"],1],["A '34-hour reset' allows you to:",["Skip inspections","Restart your weekly hour count","Avoid weigh stations","Change your route"],1],["Breaking HOS rules is called a:",["Bonus","Violation","Reset","Backhaul"],1]],"sp":["Explain the 11-hour rule, the 14-hour window, and the 30-minute break rule in your own words.","11 soatlik qoida, 14 soatlik oyna va 30 daqiqalik tanaffus qoidasini o'z so'zlaringiz bilan tushuntiring."]},
{"d":23,"w":5,"wt":"Hours of Service & Logbook","t":"Rest Breaks & Fatigue","tu":"Dam Olish va Charchoq","v":[["Fatigue","Charchoq","Fatigue is dangerous for drivers."],["Drowsy","Uyquchil","I feel drowsy — I need to stop."],["Take a break","Tanaffus qilmoq","Take a break every few hours."],["Power nap","Qisqa uyqu","A 20-minute power nap can help."],["Alert","Hushyor / Sezgir","Stay alert on long drives."],["Pull over","Chetga to'xtamoq","Pull over if you feel too tired."],["Circadian rhythm","Sirkadian ritm (biologik soat)","Your circadian rhythm affects when you feel sleepy."],["Sleep debt","Uyqu qarzi","Sleep debt builds up after many short nights."],["Microsleep","Mikro uyqu","A microsleep can last just a few seconds — and cause a crash."],["Energy drink","Energetik ichimlik","An energy drink helps, but it's not a real solution."],["Stretch break","Cho'zilish tanaffusi","Take a stretch break every couple of hours."],["Fresh air","Toza havo","Open the window for fresh air if you feel tired."],["Warning signs","Ogohlantiruvchi belgilar","Learn the warning signs of fatigue."],["Yawning","Esnash","Yawning a lot is a sign you need rest."],["Heavy eyelids","Og'ir ko'z qovoqlari","Heavy eyelids mean it's time to stop."],["Lane drift","Yo'lakdan chetga chiqish","Lane drift is a dangerous sign of fatigue."],["Rumble strip","Titratuvchi chiziq (yo'l chetida)","The rumble strip woke me up — I need a break."],["Rest before driving","Haydashdan oldin dam olish","Always rest before driving a long shift."],["Wake up call","Uyg'otish qo'ng'irog'i","Ask for a wake-up call at the truck stop."],["Fatigue management","Charchoqni boshqarish","Good fatigue management keeps you and others safe."]],"dl":[["Driver A","You sound tired. Are you okay to keep driving?","Charchagandek eshitilyapsiz. Haydashda davom etishga tayyormisiz?"],["Driver B","Honestly, I feel drowsy. I should pull over.","Rostini aytsam, uyquchilman. Chetga to'xtashim kerak."],["Driver A","Good idea. Take a power nap, even 20 minutes helps.","Yaxshi fikr. Qisqa uyqu oling, hatto 20 daqiqa ham yordam beradi."],["Driver B","You're right. Fatigue causes many accidents. I'll stop at the next rest area.","Haqsiz. Charchoq ko'plab baxtsiz hodisalarga sabab bo'ladi. Keyingi dam olish joyida to'xtayman."]],"g":["Feel + adjective","Describe your state with 'I feel...': 'I feel drowsy. I feel tired. I feel alert.' This is common and important for safety talk."],"qz":[["'Drowsy' means feeling:",["Angry","Sleepy","Hungry","Excited"],1],["What should you do if you feel drowsy while driving?",["Drink more coffee and keep going","Pull over and rest","Drive faster to arrive sooner","Turn up the music"],1],["A 'power nap' is:",["A full night's sleep","A short rest, like 20 minutes","A type of engine","A break for lunch"],1],["Fatigue is dangerous because it causes:",["Better focus","Accidents","Faster driving","More fuel savings"],1]],"sp":["Describe what you do when you start to feel tired or drowsy while driving.","Haydash paytida charchagan yoki uyquchil his qila boshlaganingizda nima qilishingizni tasvirlang."]},
{"d":24,"w":5,"wt":"Hours of Service & Logbook","t":"Logbook Problems & Corrections","tu":"Jurnaldagi Muammolar va Tuzatishlar","v":[["Edit the log","Jurnalni tahrirlamoq","You can edit the log for a small mistake."],["Malfunction","Nosozlik (texnik)","My ELD has a malfunction today."],["Certify","Tasdiqlamoq","Certify your log at the end of the day."],["Unassigned driving","Egasi noma'lum haydash","There is unassigned driving time on the truck."],["Correction","Tuzatish","I need to make a correction to yesterday's log."],["Diagnostic","Diagnostika","The ELD shows a data diagnostic event."],["Missing data","Yo'qolgan ma'lumot","There is missing data on yesterday's log."],["Edit request","Tahrirlash so'rovi","Send an edit request to your carrier."],["Driver certification","Haydovchi tasdig'i","Driver certification confirms the log is accurate."],["Supporting documents","Qo'shimcha hujjatlar","Keep supporting documents like fuel receipts."],["Time zone change","Vaqt mintaqasi o'zgarishi","The ELD adjusts automatically for a time zone change."],["Odometer discrepancy","Spidometr nomuvofiqligi","Report any odometer discrepancy to your carrier."],["ELD exemption","ELD istisnosi","Some old trucks have an ELD exemption."],["Grace period","Imtiyoz muddati","There's a short grace period for ELD malfunctions."],["Violation code","Qoidabuzarlik kodi","The inspector wrote down a violation code."],["Roadside data transfer","Yo'lda ma'lumot uzatish","Perform a roadside data transfer for the inspector."],["Inspection code","Tekshiruv kodi","Every inspection is recorded with a code."],["Compliance","Muvofiqlik (qoidaga rioya)","Compliance with HOS rules keeps you legal."],["Audit","Audit (tekshiruv)","The company may audit your logs randomly."],["Log accuracy","Jurnal aniqligi","Log accuracy is your responsibility every day."]],"dl":[["Driver","My ELD shows a malfunction. What should I do?","ELD'imda nosozlik ko'rsatilyapti. Nima qilishim kerak?"],["Support","Switch to paper logs and report it to your carrier within 24 hours.","Qog'oz jurnalga o'ting va tashuvchi kompaniyangizga 24 soat ichida xabar bering."],["Driver","Okay. Also, I see unassigned driving time — that wasn't me.","Xo'p. Shuningdek, egasi noma'lum haydash vaqtini ko'rmoqdaman — bu men emasman."],["Support","You can add a note and make a correction. Then certify your log.","Izoh qo'shib, tuzatish kiritishingiz mumkin. Keyin jurnalingizni tasdiqlang."]],"g":["Reporting a problem: 'I see / I notice'","Use 'I see' or 'I notice' to point out a problem you found: 'I notice unassigned driving time. I see a malfunction.'"],"qz":[["If your ELD malfunctions, you should switch to:",["Nothing, just keep driving","Paper logs","A different truck","Sleep mode"],1],["'Certify your log' means to:",["Delete it","Confirm it is correct","Print it","Ignore it"],1],["'Unassigned driving' means driving time that:",["Is yours","Isn't linked to any driver yet","Was deleted","Was paid extra"],1],["A 'correction' to a logbook is:",["A new truck","A fix for a mistake in the log","A type of fine","A rest break"],1]],"sp":["Explain what you would do if your ELD showed a malfunction during your trip.","Agar safar davomida ELD'ingizda nosozlik ko'rsatilsa, nima qilishingizni tushuntiring."]},
{"d":25,"w":5,"wt":"Hours of Service & Logbook","rev":true,"t":"Week 5 Review — Logbook Audit","tu":"5-hafta Takrorlash — Jurnal Auditi","qz":[["ELD stands for:",["Extra License Data","Electronic Logging Device","Engine Load Display","Emergency Locator Device"],1],["The 11-hour rule limits:",["Rest time","Driving time","Fuel stops","Loading time"],1],["A mandatory 30-minute break is required after:",["4 hours","8 hours","10 hours","12 hours"],1],["A '34-hour reset' restarts your:",["Truck engine","Weekly hour count","ELD device","Route"],1],["Feeling sleepy while driving is called:",["Alert","Drowsy","Certified","Secure"],1],["If you feel drowsy, you should:",["Keep driving fast","Pull over and rest","Turn off the ELD","Call dispatch and complain"],1],["If your ELD malfunctions, you must switch to:",["Nothing","Paper logs","A new truck","Manual mode only"],1],["'Unassigned driving' means:",["Your own driving","Driving not linked to a driver","Driving in reverse","Driving off-route"],1]],"sp":["Explain the full HOS system to a new driver: the 11-hour rule, 14-hour window, 30-minute break, 70-hour rule, and what to do if you feel tired.","Yangi haydovchiga to'liq HOS tizimini tushuntiring: 11 soatlik qoida, 14 soatlik oyna, 30 daqiqalik tanaffus, 70 soatlik qoida va charchaganda nima qilish kerakligi."]},
{"d":26,"w":6,"wt":"DOT Inspections & Police Stops","t":"Being Pulled Over","tu":"Yo'lda To'xtatilish","v":[["Pull over","To'xtang (chetga)","Pull over to the right shoulder."],["License and registration","Guvohnoma va ro'yxatga olish hujjati","License and registration, please."],["Hands on the wheel","Qo'llarni ruldan olmang","Please keep your hands on the wheel."],["Citation","Jarima varaqasi","You will receive a citation for speeding."],["Warning","Ogohlantirish","This time, I'll just give you a warning."],["Ticket","Jarima chiptasi","Sign here to accept the ticket."],["Blue lights","Ko'k chiroqlar","I saw blue lights behind me and pulled over."],["Siren","Sirena","I heard a siren and moved to the right."],["Speeding","Tezlik oshirish","I got stopped for speeding."],["Expired tag","Muddati o'tgan belgi","The officer noticed my expired registration tag."],["Fix-it ticket","Tuzatish uchun chipta","I got a fix-it ticket for the broken light."],["Court date","Sud sanasi","My court date is next month."],["Fine payment","Jarima to'lovi","You can make a fine payment online."],["Points on license","Guvohnomadagi ballar","Speeding adds points on your license."],["Plead guilty","Aybni tan olmoq","I decided to plead guilty and pay the fine."],["Plead not guilty","Aybni tan olmaslik","You can plead not guilty and go to court."],["Traffic court","Yo'l harakati sudi","I have to appear in traffic court."],["Warning letter","Ogohlantirish xati","The company sent me a warning letter."],["Remain calm","Xotirjam qoling","Remain calm and follow the officer's instructions."],["Roll down the window","Oynani tushirmoq","Roll down the window slowly when the officer arrives."]],"dl":[["Officer","Pull over to the shoulder, please.","Iltimos, chetga to'xtang."],["Driver","Yes, officer. Is there a problem?","Xo'p, ofitser. Muammo bormi?"],["Officer","License and registration, please. Keep your hands on the wheel.","Iltimos, guvohnoma va ro'yxatga olish hujjatini bering. Qo'llaringizni ruldan olmang."],["Driver","Here you go. What did I do wrong?","Mana. Nima xato qildim?"],["Officer","Your taillight is out. This time I'll give you a warning — get it fixed soon.","Orqa chirog'ingiz yonmayapti. Bu safar ogohlantirish beraman — tez orada tuzating."],["Driver","Thank you, officer. I'll fix it today.","Rahmat, ofitser. Bugun tuzataman."]],"g":["Staying calm and polite","Always say 'Yes, officer' and 'Thank you, officer.' Move slowly, keep your hands visible, and answer questions directly and politely."],"qz":[["When an officer says 'pull over', you should:",["Speed up","Stop on the shoulder safely","Ignore it","Call dispatch first"],1],["What should you keep on the steering wheel during a stop?",["Nothing","Your hands","Your documents","Your phone"],1],["A 'warning' is different from a 'ticket' because:",["It costs more","It has no fine, just a notice","It requires jail time","It's given only at weigh stations"],1],["The polite way to address a police officer is:",["Hey you","Officer / Sir / Ma'am","Buddy","No response needed"],1]],"sp":["Roleplay being pulled over: respond politely to an officer's request for your documents.","To'xtatilish holatini o'ynang: ofitserning hujjat so'rashiga xushmuomalalik bilan javob bering."]},
{"d":27,"w":6,"wt":"DOT Inspections & Police Stops","t":"DOT Roadside Inspection","tu":"DOT Yo'lda Tekshiruvi","v":[["DOT number","DOT raqami","Your DOT number must be visible on the truck."],["Inspection level","Tekshiruv darajasi","This is a Level 1 inspection — full check."],["Out of service","Xizmatdan chetlatilgan","This truck is out of service until repaired."],["Safety rating","Xavfsizlik reytingi","The company has a good safety rating."],["CSA score","CSA bali","A high CSA score can mean more inspections."],["Brake check","Tormozlarni tekshirish","The inspector is doing a brake check now."],["Level 2 inspection","2-daraja tekshiruvi","A Level 2 inspection skips going under the truck."],["Level 3 inspection","3-daraja tekshiruvi","A Level 3 inspection checks only your documents."],["Walk-around inspection","Aylanib tekshirish","The officer does a walk-around inspection first."],["Vehicle inspection report","Transport vositasi tekshiruv hisoboti","Sign the vehicle inspection report at the end."],["Defect list","Nuqsonlar ro'yxati","The inspector gave me a defect list."],["Out-of-service order","Xizmatdan chetlatish buyrug'i","An out-of-service order means the truck cannot move."],["Re-inspection","Qayta tekshiruv","You'll need a re-inspection after the repair."],["Brake adjustment","Tormozni sozlash","The brakes need a small brake adjustment."],["Steering component","Rul qismi","Inspect every steering component carefully."],["Frame damage","Rama shikastlanishi","Frame damage can put a truck out of service."],["Coupling device inspection","Ulash qurilmasini tekshirish","The coupling device inspection passed."],["Emergency equipment","Favqulodda jihozlar","Emergency equipment includes triangles and a fire extinguisher."],["Lighting devices","Yoritish qurilmalari","All lighting devices must work properly."],["Inspection sticker","Tekshiruv nishoni (stiker)","The inspection sticker shows the last inspection date."]],"dl":[["Inspector","This is a Level 1 inspection. I'll check your truck, trailer, and documents.","Bu 1-daraja tekshiruvi. Yuk mashinangiz, tirkamangiz va hujjatlaringizni tekshiraman."],["Driver","Understood. Here is my CDL and medical card.","Tushundim. Mana mening CDL va tibbiy kartam."],["Inspector","Thank you. I'm doing a brake check now — please pump the brakes when I say.","Rahmat. Hozir tormozlarni tekshiryapman — aytganimda tormozni bosing."],["Driver","Okay, ready when you are.","Xo'p, tayyorman."],["Inspector","Everything looks good. No violations. Have a safe trip.","Hammasi yaxshi ko'rinyapti. Qoidabuzarlik yo'q. Yo'lingiz xavfsiz bo'lsin."]],"g":["Passive voice for inspections","'The truck was inspected. The brakes were checked.' Passive voice is common when the action matters more than who did it — very common in official/DOT English."],"qz":[["A 'Level 1' DOT inspection checks:",["Only the driver's license","Truck, trailer, and documents fully","Only the trailer","Nothing, it's just a warning"],1],["If a truck is 'out of service', it means:",["It can keep driving","It cannot be driven until fixed","It needs fuel","It passed inspection"],1],["A company's 'safety rating' reflects:",["Fuel efficiency","How safely the company operates","Truck color","Driver's age"],1],["What documents should you show an inspector?",["Only your phone","CDL and medical card","Nothing, just wait","Only the bill of lading"],1]],"sp":["Explain what happens during a Level 1 DOT inspection.","1-daraja DOT tekshiruvi davomida nima sodir bo'lishini tushuntiring."]},
{"d":28,"w":6,"wt":"DOT Inspections & Police Stops","t":"Required Documents","tu":"Zarur Hujjatlar","v":[["CDL (Commercial Driver's License)","Tijorat haydovchilik guvohnomasi","Always carry your CDL."],["Medical card","Tibbiy karta","Your medical card must not be expired."],["Registration","Ro'yxatga olish hujjati","The registration is in the glove box."],["Proof of insurance","Sug'urta hujjati","Show proof of insurance if asked."],["IFTA","IFTA (yoqilg'i solig'i hujjati)","Keep your IFTA sticker updated."],["Bill of lading","Yuk hujjati (BOL)","The bill of lading lists the cargo details."],["Driver qualification file","Haydovchi malaka fayli","The driver qualification file is kept by the company."],["Drug test card","Narkotik test kartasi","Carry your drug test card if required."],["Hazmat certificate","Xavfli yuk sertifikati","A hazmat certificate is needed for dangerous cargo."],["Trip permit","Safar ruxsatnomasi","Some states require a trip permit."],["Fuel tax permit","Yoqilg'i solig'i ruxsatnomasi","Keep your fuel tax permit up to date."],["Weight/distance permit","Og'irlik/masofa ruxsatnomasi","Some states need a weight/distance permit."],["Lease agreement","Ijara shartnomasi","Read your lease agreement carefully."],["Insurance certificate","Sug'urta sertifikati","Show your insurance certificate if asked."],["Accident report form","Baxtsiz hodisa hisobot shakli","Fill out the accident report form completely."],["Company safety policy","Kompaniya xavfsizlik siyosati","Follow the company safety policy at all times."],["Emergency contact card","Favqulodda aloqa kartasi","Keep an emergency contact card in your wallet."],["ID badge","ID nishon","Wear your ID badge at the warehouse."],["Vehicle registration","Transport vositasi ro'yxati","Your vehicle registration must not be expired."],["Permit book","Ruxsatnomalar kitobi","Keep your permit book in the truck."]],"dl":[["Officer","Do you have your CDL, medical card, and proof of insurance?","CDL, tibbiy karta va sug'urta hujjatingiz bormi?"],["Driver","Yes, here they are. My registration is current too.","Ha, mana ular. Ro'yxatga olish hujjatim ham amal qilyapti."],["Officer","Good. What about your bill of lading for this load?","Yaxshi. Bu yuk uchun BOL hujjatingiz-chi?"],["Driver","Right here. It shows the cargo, weight, and delivery address.","Mana. Unda yuk, og'irlik va yetkazib berish manzili ko'rsatilgan."],["Officer","Everything checks out. Thank you.","Hammasi joyida. Rahmat."]],"g":["'Must not be expired'","For legal documents, say: 'Your license must not be expired. Your medical card must be current/valid.' 'Expired' = no longer valid."],"qz":[["A 'medical card' proves that:",["You paid your taxes","You are physically fit to drive","You own the truck","You passed a DOT inspection"],1],["The document that lists your cargo details is the:",["CDL","Bill of lading","Medical card","IFTA sticker"],1],["'Proof of insurance' shows that:",["You have a license","Your truck is insured","You paid tolls","You inspected the truck"],1],["If a document is 'expired', it is:",["Still valid","No longer valid","Lost","New"],1]],"sp":["List all the documents a truck driver must carry and explain what each one is for.","Haydovchi olib yurishi kerak bo'lgan barcha hujjatlarni sanab, har birining vazifasini tushuntiring."]},
{"d":29,"w":6,"wt":"DOT Inspections & Police Stops","t":"Common Officer Questions & Answers","tu":"Ofitsyerning Odatiy Savollari va Javoblar","v":[["Where are you headed?","Qayerga ketyapsiz?","Where are you headed today? — I'm headed to Phoenix."],["What are you hauling?","Nima tashiyapsiz?","What are you hauling? — I'm hauling furniture."],["How long have you been driving?","Qancha vaqtdan beri haydayapsiz?","How long have you been driving today? — About 5 hours."],["Do you have any violations?","Qoidabuzarliklaringiz bormi?","Do you have any violations on your record? — No, clean record."],["Where did you start your trip?","Safaringizni qayerdan boshladingiz?","I started in Los Angeles this morning."],["Can I see your logbook?","Jurnalingizni ko'rsam bo'ladimi?","Can I see your logbook? — Yes, here it is on the ELD."],["What company do you work for?","Qaysi kompaniyada ishlaysiz?","What company do you work for? — Speedline Logistics."],["Is this your truck?","Bu sizning mashinangizmi?","Is this your truck? — No, it belongs to the company."],["Step out of the vehicle","Mashinadan chiqing","Please step out of the vehicle."],["Open the trailer doors","Tirkama eshiklarini oching","Can you open the trailer doors, please?"],["Any mechanical issues?","Texnik muammolar bormi?","Any mechanical issues today? — No, everything is fine."],["When was your last inspection?","Oxirgi tekshiruv qachon bo'lgan?","When was your last inspection? — Two weeks ago."],["Do you have a hazmat load?","Xavfli yukingiz bormi?","Do you have a hazmat load? — No, just furniture."],["What's in the trailer?","Tirkamada nima bor?","What's in the trailer? — Electronics, on pallets."],["How much does the truck weigh?","Mashina qancha og'irlikda?","How much does the truck weigh? — About 78,000 pounds."],["Is the cargo secured?","Yuk mahkamlanganmi?","Is the cargo secured? — Yes, with straps and a tarp."],["Any recent accidents?","So'nggi paytda avariya bo'lganmi?","Any recent accidents? — No, my record is clean."],["I consent","Roziman","I consent to the inspection, officer."],["Everything looks fine","Hammasi yaxshi ko'rinyapti","Everything looks fine, you're free to go."],["Have your documents ready","Hujjatlaringizni tayyorlab qo'ying","Have your documents ready before the officer arrives."]],"dl":[["Officer","Where are you headed today?","Bugun qayerga ketyapsiz?"],["Driver","I'm headed to Phoenix, Arizona.","Arizona shtatidagi Phoenix shahriga ketyapman."],["Officer","What are you hauling?","Nima tashiyapsiz?"],["Driver","I'm hauling furniture, dry van trailer.","Mebel tashiyapman, yopiq tirkamada."],["Officer","How long have you been driving today?","Bugun qancha vaqtdan beri haydayapsiz?"],["Driver","About 5 hours. Here is my ELD log if you'd like to see it.","Taxminan 5 soat. Agar ko'rishni istasangiz, mana ELD jurnalim."]],"g":["Present perfect: 'How long have you been driving?'","This question asks about a duration up to now. Answer with 'for' + time: 'I've been driving for 5 hours.'"],"qz":[["'What are you hauling?' is asking about your:",["Route","Cargo","Speed","Truck color"],1],["The correct answer format for 'How long have you been driving?' is:",["'Yesterday'","'For 5 hours'","'Fast'","'Phoenix'"],1],["'Where are you headed?' asks about your:",["Starting point","Destination","Weight","License"],1],["If an officer asks for your logbook, you should:",["Refuse","Show your ELD log","Say you don't have one","Drive away"],1]],"sp":["Answer these officer questions out loud: Where are you headed? What are you hauling? How long have you been driving?","Ushbu ofitser savollariga ovoz chiqarib javob bering: Qayerga ketyapsiz? Nima tashiyapsiz? Qancha vaqtdan beri haydayapsiz?"]},
{"d":30,"w":6,"wt":"DOT Inspections & Police Stops","rev":true,"t":"Week 6 Review — Inspection Simulation (Halfway Point!)","tu":"6-hafta Takrorlash — Tekshiruv Simulyatsiyasi (Yarim Yo'l!)","qz":[["When pulled over, you should keep your hands:",["In your pockets","On the steering wheel","Behind your back","On your phone"],1],["A 'citation' is also called a:",["Bonus","Ticket","Reset","Backhaul"],1],["A Level 1 DOT inspection checks:",["Only your license","Truck, trailer, and all documents","Only the trailer tires","Nothing important"],1],["If your truck is 'out of service', you:",["Can keep driving carefully","Cannot drive until it's fixed","Must call a tow immediately","Get a bonus"],1],["The 'bill of lading' lists:",["Your salary","Cargo details","Your driving hours","Fuel prices"],1],["'Proof of insurance' proves your truck is:",["Registered","Insured","Inspected","Fast"],1],["'What are you hauling?' asks about your:",["Cargo","License","Insurance","Speed"],0],["An expired document is one that is:",["New","No longer valid","Free","Required only sometimes"],1]],"sp":["Full roleplay: you are pulled over for a Level 1 DOT inspection. Answer the officer's questions and present your documents.","To'liq rolli o'yin: siz 1-daraja DOT tekshiruvi uchun to'xtatildingiz. Ofitserning savollariga javob bering va hujjatlaringizni taqdim eting."]},
{"d":31,"w":7,"wt":"Weigh Stations & Scales","t":"Weigh Station Basics","tu":"Tarozi Bekati Asoslari","v":[["Weigh station","Tarozi bekati","Pull into the weigh station ahead."],["Scale","Tarozi","Drive slowly onto the scale."],["Gross weight","Umumiy og'irlik","The gross weight is 78,000 pounds."],["Axle weight","O'q og'irligi","Check the axle weight before you leave."],["Overweight","Ortiqcha og'irlik","Your trailer is overweight by 2,000 pounds."],["Open / Closed","Ochiq / Yopiq","The weigh station is open tonight."],["Static scale","Statik tarozi","Pull slowly onto the static scale."],["Weigh-in-motion","Harakatdagi tortish tizimi","Weigh-in-motion scales weigh you while driving slowly."],["Axle group","O'qlar guruhi","The axle group weight must be within limits."],["Steer axle","Rul o'qi","The steer axle carries the front weight."],["Drive axle","Harakatlantiruvchi o'q","The drive axles power the truck forward."],["Trailer axle","Tirkama o'qi","The trailer axles support the cargo weight."],["Certified weight","Tasdiqlangan og'irlik","Get a certified weight ticket after loading."],["Scale ticket","Tarozi cheki","Keep the scale ticket with your paperwork."],["Scale operator","Tarozi operatori","Ask the scale operator if you have questions."],["Re-weigh request","Qayta tortish so'rovi","You can make a re-weigh request if you disagree."],["Overweight citation","Ortiqcha og'irlik uchun jarima","An overweight citation can be very costly."],["Weight distribution","Og'irlik taqsimoti","Good weight distribution keeps you legal."],["Tandem slide","Tandem siljitish","Adjust the tandem slide to balance the axles."],["Kingpin setting","King-pin sozlamasi","Check your kingpin setting before weighing."]],"dl":[["Officer","Pull onto the scale slowly, please.","Iltimos, tarozi ustiga sekin haydang."],["Driver","Okay, I'm on the scale now.","Xo'p, hozir tarozi ustidaman."],["Officer","Your gross weight is 79,500 pounds. That's within the limit.","Umumiy og'irligingiz 79,500 funt. Bu chegara doirasida."],["Driver","Great, thank you. Can I go now?","Ajoyib, rahmat. Endi keta olamanmi?"],["Officer","Yes, you're clear. Have a safe trip.","Ha, siz ketishingiz mumkin. Yo'lingiz xavfsiz bo'lsin."]],"g":["Weight expressions","Say weight like this: '79,500 pounds' = 'seventy-nine thousand five hundred pounds.' Large numbers are read in groups of thousands."],"qz":[["At a weigh station, you drive onto the:",["Ramp","Scale","Dock","Shoulder"],1],["'Gross weight' means:",["Only the trailer's weight","Total weight of truck + trailer + cargo","Only the cargo weight","The empty truck's weight"],1],["If your truck is 'overweight', it means:",["It's under the legal limit","It's over the legal weight limit","It needs fuel","It failed inspection"],1],["If a weigh station is 'closed', you should:",["Stop anyway","Continue driving past it","Wait there all night","Call the police"],1]],"sp":["Explain what happens when you go through a weigh station, step by step.","Tarozi bekatidan o'tganingizda nima sodir bo'lishini qadam-baqadam tushuntiring."]},
{"d":32,"w":7,"wt":"Weigh Stations & Scales","t":"Weight Limits & Permits","tu":"Og'irlik Chegaralari va Ruxsatnomalar","v":[["Legal weight","Qonuniy og'irlik","80,000 pounds is the standard legal weight."],["Permit","Ruxsatnoma","You need a permit for a heavier load."],["Oversize","Katta o'lcham","This load is oversize and needs a permit."],["Escort","Kuzatuvchi (mashina)","An escort vehicle must follow the oversize load."],["Axle spacing","O'qlar orasidagi masofa","Axle spacing affects your legal weight limit."],["Fine","Jarima","An overweight fine can be very expensive."],["Bridge law formula","Ko'prik qonuni formulasi","The bridge law formula limits weight by axle spacing."],["Single axle limit","Yagona o'q chegarasi","The single axle limit is usually 20,000 pounds."],["Tandem axle limit","Tandem o'q chegarasi","The tandem axle limit is usually 34,000 pounds."],["Superload","Super yuk (juda katta)","A superload needs special state approval."],["Annual permit","Yillik ruxsatnoma","Buy an annual permit if you haul oversize often."],["Multi-state permit","Ko'p shtatli ruxsatnoma","A multi-state permit covers several states."],["Route survey","Marshrut tekshiruvi","A route survey checks bridges and clearances."],["Pilot car","Kuzatuvchi mashina (pilot)","A pilot car leads the oversize load."],["Height pole","Balandlik ustuni","The pilot car has a height pole to check clearance."],["Curfew hours","Man qilingan soatlar","Oversize loads can't move during curfew hours."],["Permit fee","Ruxsatnoma to'lovi","The permit fee depends on the weight."],["Weight enforcement","Og'irlikni nazorat qilish","Weight enforcement officers patrol the highways."],["Citation amount","Jarima summasi","The citation amount increases with more overweight."],["Legal axle weight","Qonuniy o'q og'irligi","Stay within the legal axle weight at all times."]],"dl":[["Officer","Your truck is 3,000 pounds overweight.","Yuk mashinangiz 3,000 funt ortiqcha og'irlikda."],["Driver","I didn't know. What happens now?","Bilmasdim. Endi nima bo'ladi?"],["Officer","You'll receive a fine, and you need to redistribute or drop some weight.","Sizga jarima yoziladi va og'irlikni qayta taqsimlashingiz yoki kamaytirishingiz kerak."],["Driver","Do I need a special permit for this weight?","Bu og'irlik uchun maxsus ruxsatnoma kerakmi?"],["Officer","Yes, an overweight permit, or you must reduce the load to the legal limit.","Ha, ortiqcha og'irlik ruxsatnomasi, yoki yukni qonuniy chegaragacha kamaytirishingiz kerak."]],"g":["Cause and effect: 'because' / 'so'","'The load is heavy, so I need a permit.' / 'I need a permit because the load is oversize.' Practice connecting ideas with because/so."],"qz":[["The standard legal gross weight limit in the US is usually:",["50,000 lbs","65,000 lbs","80,000 lbs","100,000 lbs"],2],["An 'oversize' load usually needs a(n):",["Extra driver","Permit and sometimes an escort","New trailer","Faster route"],1],["'Axle spacing' affects:",["Fuel type","Legal weight limits","Tire color","Insurance cost"],1],["If you're overweight, you might need to:",["Speed up","Redistribute or drop weight","Ignore it","Add more cargo"],1]],"sp":["Explain what a driver should do if the scale shows the truck is overweight.","Agar tarozi yuk mashinasining ortiqcha og'irlikda ekanini ko'rsatsa, haydovchi nima qilishi kerakligini tushuntiring."]},
{"d":33,"w":7,"wt":"Weigh Stations & Scales","t":"Bypass Systems (PrePass, Drivewyze)","tu":"Bypass Tizimlari (PrePass, Drivewyze)","v":[["Transponder","Transponder (signal qurilma)","The transponder is mounted on your windshield."],["Bypass","Chetlab o'tish","With a bypass, you can skip the scale."],["Green light","Yashil chiroq","A green light means you can bypass."],["Red light","Qizil chiroq","A red light means pull into the station."],["Pull in","Kirmoq (bekatga)","Pull in — the system gave you a red light."],["Mainline","Asosiy yo'l","Stay on the mainline if you get bypassed."],["RFID tag","RFID belgisi (chip)","The RFID tag is scanned automatically."],["Enrollment","Ro'yxatdan o'tish","Enrollment in PrePass is free for most carriers."],["Account balance","Hisob balansi","Check your account balance for the bypass service."],["Screening","Skrining (tekshiruv)","The system does automatic safety screening."],["Safety score","Xavfsizlik bali","A good safety score increases your bypass rate."],["Bypass rate","Chetlab o'tish darajasi","My bypass rate is over 90 percent."],["Antenna","Antenna","Mount the antenna on your windshield."],["System outage","Tizim ishlamay qolishi","During a system outage, pull into the station."],["Manual override","Qo'lda boshqarish","Use manual override if the transponder fails."],["Toll integration","Yo'l puli integratsiyasi","Some transponders also work for toll integration."],["Membership fee","A'zolik to'lovi","There's a small monthly membership fee."],["Real-time data","Real vaqt ma'lumoti","The system uses real-time data to decide bypass."],["Compliance history","Muvofiqlik tarixi","Your compliance history affects your bypass rate."],["Transponder mount","Transponder o'rnatish joyi","Clean the transponder mount before installing it."]],"dl":[["Driver A","Do you use PrePass or Drivewyze?","Siz PrePass yoki Drivewyze ishlatasizmi?"],["Driver B","Both — my transponder is mounted on the windshield.","Ikkalasini ham — transponderim old oynada o'rnatilgan."],["Driver A","What happens if you get a green light?","Yashil chiroq yonsa, nima bo'ladi?"],["Driver B","I stay on the mainline and bypass the scale completely. Red light means I pull in.","Men asosiy yo'lda qolib, tarozini butunlay chetlab o'taman. Qizil chiroq bo'lsa, bekatga kiraman."]],"g":["Conditional 'if'","'If you get a green light, you can bypass. If it's red, you must pull in.' This 'if' structure is used for rules and instructions."],"qz":[["A bypass system like PrePass allows you to:",["Skip fueling","Skip the weigh station scale","Skip inspections forever","Skip paying tolls"],1],["A green light from the bypass system means:",["Pull in for inspection","You may continue on the mainline","Stop immediately","Turn around"],1],["A red light from the bypass system means:",["Continue driving","Pull into the weigh station","Speed up","Call dispatch"],1],["A transponder is usually mounted on the:",["Trailer door","Windshield","Fuel tank","Mirror only"],1]],"sp":["Explain how a bypass system like PrePass works, using 'if/then' sentences.","PrePass kabi bypass tizimi qanday ishlashini 'agar/unda' gaplaridan foydalanib tushuntiring."]},
{"d":34,"w":7,"wt":"Weigh Stations & Scales","t":"Handling Weight Problems","tu":"Og'irlik Muammolarini Hal Qilish","v":[["Shift the load","Yukni siljitmoq","Shift the load forward to balance the axles."],["Redistribute","Qayta taqsimlamoq","Redistribute the weight between axles."],["Drop weight","Og'irlikni kamaytirmoq","We need to drop some weight at the yard."],["Split load","Yukni bo'lmoq","We'll split the load between two trucks."],["Reweigh","Qayta tortmoq","Reweigh the truck after adjusting the load."],["Weight ticket","Og'irlik cheki","Keep the weight ticket for your records."],["Load bar","Yuk to'sig'i (bar)","Use a load bar to keep boxes from shifting."],["Load lock","Yuk qulfi","Install a load lock across the trailer."],["Portable axle scale","Ko'chma o'q tarozisi","Use a portable axle scale to check weight early."],["CAT scale","CAT tarozisi","Stop at a CAT scale to verify your weight."],["Weight distribution chart","Og'irlik taqsimoti jadvali","Use a weight distribution chart to plan your load."],["Sliding tandems","Siljiydigan tandem o'qlar","Adjust the sliding tandems to fix the axle weight."],["Nose weight","Old qism og'irligi","Check the nose weight on the fifth wheel."],["Overload risk","Ortiqcha yuklash xavfi","An overload risk can damage the suspension."],["Structural damage","Tuzilma shikastlanishi","Overweight loads can cause structural damage."],["Suspension stress","Osma tizim zo'riqishi","Too much weight causes suspension stress."],["Fine negotiation","Jarima bo'yicha muzokara","Fine negotiation is possible in some states."],["Weight slip","Og'irlik varag'i","Keep the weight slip until delivery."],["Axle reconfiguration","O'qlarni qayta joylashtirish","Axle reconfiguration can fix an overweight axle."],["Legal limit check","Qonuniy chegarani tekshirish","Always do a legal limit check before the highway."]],"dl":[["Driver","The scale shows my rear axle is overweight.","Tarozi orqa o'qim ortiqcha og'irlikda ekanini ko'rsatyapti."],["Yard worker","Let's shift the load forward and redistribute the weight.","Yukni oldinga siljitib, og'irlikni qayta taqsimlaylik."],["Driver","Okay. Should I reweigh after that?","Xo'p. Shundan keyin qayta tortishim kerakmi?"],["Yard worker","Yes, always reweigh to confirm. Keep the new weight ticket.","Ha, tasdiqlash uchun doim qayta torting. Yangi og'irlik chekini saqlab qo'ying."]],"g":["Suggestions with 'let's'","'Let's shift the load. Let's reweigh it.' Use 'let's' + verb to suggest doing something together."],"qz":[["If your rear axle is overweight, you might need to:",["Add more cargo","Shift the load forward","Drive faster","Ignore it"],1],["After adjusting the load, you should:",["Leave immediately","Reweigh to confirm","Call the police","Remove the tarp"],1],["A 'weight ticket' is:",["A speeding fine","A receipt showing the weight","A parking permit","A fuel receipt"],1],["'Split load' means:",["Dividing cargo between two trucks","Breaking the trailer","Deleting the logbook","Doubling the weight"],0]],"sp":["Explain 3 ways a driver can fix an overweight problem.","Haydovchi ortiqcha og'irlik muammosini hal qilishning 3 usulini tushuntiring."]},
{"d":35,"w":7,"wt":"Weigh Stations & Scales","rev":true,"t":"Week 7 Review — Scale House Challenge","tu":"7-hafta Takrorlash — Tarozi Uyi Sinovi","qz":[["At a weigh station, you drive onto the:",["Dock","Scale","Ramp","Shoulder"],1],["'Gross weight' includes:",["Only cargo","Truck + trailer + cargo","Only the trailer","Only the fuel"],1],["The standard legal weight limit is usually:",["65,000 lbs","70,000 lbs","80,000 lbs","90,000 lbs"],2],["An oversize load usually requires a:",["Faster truck","Permit","New CDL","Different fuel"],1],["A green light from a bypass system means:",["Pull in","Continue on the mainline","Stop and wait","Turn around"],1],["A red light means you should:",["Continue driving","Pull into the weigh station","Turn off the engine","Call 911"],1],["If overweight, one solution is to:",["Add more cargo","Redistribute or drop weight","Speed up","Ignore the scale"],1],["A 'weight ticket' is a record of your:",["Speed","Weight","Fuel","Route"],1]],"sp":["Explain the full weigh station process: pulling in, getting weighed, and what happens if you're overweight.","To'liq tarozi bekati jarayonini tushuntiring: kirish, tortilish va agar ortiqcha og'irlikda bo'lsangiz nima bo'lishi."]},
{"d":36,"w":8,"wt":"Dispatch & Phone Communication","t":"Calling Dispatch","tu":"Dispetcherga Qo'ng'iroq Qilish","v":[["Dispatcher","Dispetcher","My dispatcher assigns my loads."],["Check call","Nazorat qo'ng'irog'i","This is my scheduled check call."],["Load number","Yuk raqami","Please confirm the load number."],["Empty / Loaded","Bo'sh / Yuklangan","I am empty now, ready for a new load."],["Layover","Kutish vaqti (yuksiz)","I have a layover until tomorrow morning."],["Breakdown report","Buzilish haqida hisobot","I need to file a breakdown report."],["Load confirmation","Yuk tasdiqlash hujjati","Send me the load confirmation for tomorrow."],["Rate confirmation","Narx tasdiqlash hujjati","The rate confirmation shows the pay for this load."],["Broker","Broker (vositachi)","The broker set up this load for us."],["Carrier","Tashuvchi kompaniya","Our carrier number is on the truck door."],["Shipper contact","Jo'natuvchi aloqa raqami","Call the shipper contact before you arrive."],["Receiver contact","Qabul qiluvchi aloqa raqami","Save the receiver contact number."],["Trip number","Safar raqami","Give dispatch your trip number for this load."],["Unit number","Mashina raqami (unit)","My unit number is 214."],["Trailer number","Tirkama raqami","The trailer number is printed on the front."],["Fuel level report","Yoqilg'i darajasi hisoboti","Give dispatch a fuel level report."],["Next available time","Keyingi bo'sh vaqt","What's your next available time for a load?"],["Home time request","Uyga borish so'rovi","I'd like to submit a home time request."],["Time off request","Ta'til so'rovi","My time off request was approved."],["Load board","Yuk taxtasi (topshiriqlar)","Check the load board for open loads."]],"dl":[["Driver","Hi, this is Jasur, truck 214, calling in for my check call.","Salom, bu Jasur, 214-raqamli mashina, nazorat qo'ng'irog'i uchun qo'ng'iroq qilyapman."],["Dispatcher","Hi Jasur, go ahead. What's your status?","Salom Jasur, ayting. Holatingiz qanday?"],["Driver","I just delivered — I'm empty now. Load number 4471 is complete.","Hozirgina yetkazib berdim — hozir bo'shman. 4471-raqamli yuk tugallandi."],["Dispatcher","Great. I have your next load ready. Are you okay with a layover tonight?","Ajoyib. Keyingi yukingiz tayyor. Bugun kechqurun kutib turishga rozimisiz?"],["Driver","Yes, that's fine. Send me the details.","Ha, bu yaxshi. Menga tafsilotlarni yuboring."]],"g":["Reporting status: 'I am / I have'","Report your status simply: 'I am empty. I am loaded. I have a layover.' These short reports are standard on check calls."],"qz":[["A 'check call' is when a driver:",["Checks the engine","Calls dispatch to report status","Checks the weather","Calls a mechanic"],1],["'I am empty' means:",["I have no fuel","I have no cargo","I am tired","I am lost"],1],["A 'layover' means:",["Extra driving time","Waiting time with no load","A type of trailer","A weigh station"],1],["If your truck breaks down, you should:",["Keep driving","File a breakdown report","Ignore it","Wait a week to report it"],1]],"sp":["Make a check call to dispatch: give your name, truck number, and current status (loaded/empty).","Dispetcherga nazorat qo'ng'irog'ini qiling: ismingiz, mashina raqamingiz va joriy holatingizni (yuklangan/bo'sh) ayting."]},
{"d":37,"w":8,"wt":"Dispatch & Phone Communication","t":"Phone Etiquette","tu":"Telefon Odob-Axloq Qoidalari","v":[["Hold on, one moment please","Biroz kuting, bir daqiqa","Hold on, one moment please, I'm parking."],["Can you repeat that?","Buni qaytara olasizmi?","Sorry, can you repeat that? The signal is bad."],["I didn't catch that","Men buni tushunmadim","I didn't catch that, could you say it again?"],["Speak up, please","Balandroq gapiring, iltimos","Speak up, please, I can barely hear you."],["Voicemail","Ovozli xabar","Leave a voicemail if I don't answer."],["Call you back","Sizga qayta qo'ng'iroq qilaman","I'll call you back in 10 minutes."],["Please hold","Iltimos, kuting","Please hold while I check the schedule."],["Transfer the call","Qo'ng'iroqni o'tkazish","I'll transfer the call to dispatch."],["Leave a message","Xabar qoldirish","Please leave a message after the beep."],["Return the call","Qo'ng'iroqqa javob qaytarish","I'll return the call in ten minutes."],["Wrong number","Noto'g'ri raqam","Sorry, you have the wrong number."],["Bad connection","Yomon aloqa","Sorry, we have a bad connection."],["Dropped call","Uzilib qolgan qo'ng'iroq","Sorry about the dropped call, let's continue."],["Text back","SMS orqali javob berish","I'll text back once I'm parked."],["Missed call","O'tkazib yuborilgan qo'ng'iroq","You have a missed call from dispatch."],["Caller ID","Qo'ng'iroq qiluvchi ID","I saw dispatch on the caller ID."],["Speaker phone","Karnay rejimi (speaker)","I'm putting you on speaker phone."],["Business hours","Ish soatlari","The office is open during business hours."],["Voicemail box","Ovozli xabarlar qutisi","Leave a message in my voicemail box."],["Confirm receipt","Qabul qilinganini tasdiqlash","Please confirm receipt of this message."]],"dl":[["Dispatcher","Can you confirm the delivery address?","Yetkazib berish manzilini tasdiqlay olasizmi?"],["Driver","Sorry, can you repeat that? The signal is bad here.","Kechirasiz, qaytara olasizmi? Bu yerda signal yomon."],["Dispatcher","I said, can you confirm the delivery address?","Men yetkazib berish manzilini tasdiqlay olasizmi dedim."],["Driver","I didn't catch the street name. Could you speak up, please?","Ko'cha nomini tushunmadim. Balandroq gapira olasizmi, iltimos?"],["Dispatcher","No problem. I'll text it to you instead.","Muammo emas. Buning o'rniga sizga SMS orqali yuboraman."]],"g":["Polite phone phrases","On the phone, use polite fillers: 'Hold on, one moment.' 'Sorry, can you repeat that?' These are much more professional than staying silent or saying 'what?'"],"qz":[["'Can you repeat that?' is used when you:",["Understood everything","Didn't hear or understand","Are angry","Want to hang up"],1],["'Speak up, please' means:",["Talk quieter","Talk louder","Talk faster","Stop talking"],1],["If you can't answer a call, the caller might leave a:",["Text only","Voicemail","Fax","Letter"],1],["'I'll call you back' means:",["I will never call","I will call again later","I am calling now","I don't have a phone"],1]],"sp":["Practice a phone call where the connection is bad: ask the other person to repeat and speak up.","Aloqa yomon bo'lgan telefon suhbatini mashq qiling: suhbatdoshdan qaytarishni va balandroq gapirishni so'rang."]},
{"d":38,"w":8,"wt":"Dispatch & Phone Communication","t":"CB Radio Lingo","tu":"CB Radio Atamalari","v":[["10-4","Tushunarli / Qabul qilindi","10-4, I copy that."],["Breaker breaker","Diqqat, gapirmoqchiman (CB radio)","Breaker breaker, anyone on this channel?"],["Smokey / Bear","Politsiya (jargon)","Careful, there's a smokey at mile marker 90."],["Chicken coop","Tarozi bekati (jargon)","The chicken coop is open tonight."],["Back door / Front door","Orqada / Oldinda (jargon)","I've got your back door, go ahead and pass."],["What's your 20?","Qayerdasiz? (joylashuv)","Hey, what's your 20?"],["Handle","Taxallus (radio nomi)","My handle on the radio is 'Silk Road'."],["Convoy","Karvon","We're driving in a convoy of three trucks."],["Rubber duck","Yetakchi (jargon)","The rubber duck is leading the convoy."],["Four-wheeler","Yengil mashina (jargon)","Watch out for that four-wheeler cutting in."],["Eighteen-wheeler","O'n sakkiz g'ildirakli (yuk mashinasi)","That eighteen-wheeler is hauling steel."],["Keep the shiny side up","Xavfsiz haydang (jargon)","Keep the shiny side up out there!"],["Wall-to-wall","Tirbandlik (jargon)","Traffic is wall-to-wall near the city."],["Roger that","Tushundim (radio)","Roger that, I'll take the next exit."],["Negative","Yo'q (radio)","Negative, I don't see a smokey."],["Affirmative","Ha (radio)","Affirmative, I'm right behind you."],["Over and out","Tugatdim (radio)","Thanks for the heads up, over and out."],["Home twenty","Uy manzili (jargon)","My home twenty is in Chicago."],["Comeback","Javob (radio)","I got a comeback from another driver."],["Ratchet jaw","Ko'p gapiruvchi (jargon)","He's a real ratchet jaw on the radio."]],"dl":[["Driver A","Breaker breaker, anyone headed east on I-80?","Diqqat, kimdir I-80 bo'ylab sharqqa ketyaptimi?"],["Driver B","10-4, I'm right behind you. What's your 20?","Qabul qilindi, men to'g'ridan-to'g'ri orqangizdaman. Qayerdasiz?"],["Driver A","Mile marker 145. Heads up, there's a smokey at mile 150.","145-milya belgisida. Ehtiyot bo'ling, 150-milyada politsiya bor."],["Driver B","Thanks for the heads up. I've got your back door.","Ogohlantirganingiz uchun rahmat. Men sizning orqangizdaman."]],"g":["CB radio culture","CB radio slang builds community between drivers. It's informal — use it with other drivers on the radio, not with officers or dispatch."],"qz":[["'10-4' means:",["I disagree","Message received/understood","Emergency","Goodbye"],1],["A 'smokey' or 'bear' refers to:",["A mechanic","A police officer","A weigh station","A rest area"],1],["'Chicken coop' is slang for a:",["Truck stop","Weigh station","Gas station","Restaurant"],1],["'What's your 20?' is asking for your:",["Speed","Location","Weight","Fuel level"],1]],"sp":["Use CB radio slang to warn another driver about a police officer ahead.","CB radio jargonidan foydalanib, boshqa haydovchini oldinda politsiya borligi haqida ogohlantiring."]},
{"d":39,"w":8,"wt":"Dispatch & Phone Communication","t":"Reporting Problems to Dispatch","tu":"Dispetcherga Muammolarni Xabar Qilish","v":[["Delay","Kechikish","There's a delay due to traffic."],["Traffic jam","Tirbandlik","I'm stuck in a traffic jam on I-95."],["Flat tire","Teshilgan shina","I have a flat tire, I need to pull over."],["Running late","Kechikib qolyapman","I'm running late — I'll arrive an hour after ETA."],["Detention time","Kutish vaqti (yuklashda)","I have two hours of detention time at the dock."],["Reschedule","Qayta rejalashtirmoq","We need to reschedule the delivery for tomorrow."],["ETA update","Yetib borish vaqti yangilanishi","I'll send an ETA update after the fuel stop."],["Root cause","Asosiy sabab","The root cause of the delay was traffic."],["Service ticket","Xizmat chiptasi","Open a service ticket for the repair."],["Claim number","Da'vo raqami","Write down the claim number for the damage."],["Incident number","Hodisa raqami","The dispatcher gave me an incident number."],["Follow-up call","Qo'shimcha qo'ng'iroq","I'll make a follow-up call in an hour."],["Status update","Holat yangilanishi","Please send a status update every two hours."],["Escalation","Yuqoriga yo'naltirish","This issue needs escalation to a supervisor."],["Supervisor","Nazoratchi","Ask to speak to a supervisor if needed."],["On-call manager","Navbatchi menejer","Call the on-call manager after hours."],["Backup plan","Zaxira reja","We need a backup plan in case of delay."],["Resolution time","Hal qilish vaqti","What's the expected resolution time?"],["Customer notification","Mijozga xabar berish","Dispatch will handle the customer notification."],["Delay reason code","Kechikish sababi kodi","Enter the delay reason code in the app."]],"dl":[["Driver","Dispatch, I have a flat tire on I-95. I'm pulling over.","Dispetcher, I-95'da shinam teshildi. Chetga to'xtayapman."],["Dispatcher","Copy that. Are you safe? I'll send roadside assistance.","Qabul qilindi. Xavfsizmisiz? Yordam xizmatini yuboraman."],["Driver","Yes, I'm safe on the shoulder. This will cause a delay — I'll be running late.","Ha, men banketda xavfsizman. Bu kechikishga olib keladi — kechikib qolaman."],["Dispatcher","Understood. I'll call the customer and reschedule the delivery window.","Tushundim. Mijozga qo'ng'iroq qilib, yetkazib berish vaqtini qayta rejalashtiraman."]],"g":["Explaining delays: 'due to'","Use 'due to' + noun to explain a cause: 'delayed due to traffic. Late due to a flat tire.' This sounds professional in reports."],"qz":[["If you have a flat tire, you should first:",["Keep driving","Pull over safely","Call the customer","Ignore it"],1],["'Running late' means:",["Arriving early","Arriving after the expected time","Not moving","Out of fuel"],1],["'Detention time' refers to time spent:",["Driving","Waiting to load/unload at a dock","Sleeping","Fueling"],1],["'Due to traffic' explains:",["A result","A cause/reason","A location","A weight"],1]],"sp":["Report a problem to dispatch: you have a flat tire and will be running late. Explain the situation.","Dispetcherga muammoni xabar qiling: shinangiz teshilgan va kechikib qolasiz. Vaziyatni tushuntiring."]},
{"d":40,"w":8,"wt":"Dispatch & Phone Communication","rev":true,"t":"Week 8 Review — Dispatch Call Simulation","tu":"8-hafta Takrorlash — Dispetcher Qo'ng'irog'i Simulyatsiyasi","qz":[["A 'check call' is used to:",["Check the weather","Report your status to dispatch","Check tire pressure","Call 911"],1],["'I am loaded' means:",["You are tired","Your truck has cargo","Your truck is empty","You are at a weigh station"],1],["'Can you repeat that?' is used when you:",["Understand fully","Didn't hear well","Are angry","Are finished talking"],1],["'10-4' on the CB radio means:",["Emergency","Understood","Goodbye","I disagree"],1],["A 'smokey' is CB slang for:",["A truck stop","A police officer","A mechanic","Bad weather"],1],["'Detention time' happens:",["While driving","While waiting to load/unload","While sleeping","While fueling"],1],["If you have a breakdown, you should:",["Keep driving","Report it to dispatch","Wait silently","Call a friend only"],1],["'Due to traffic' is used to explain a:",["Location","Reason for delay","Type of cargo","Fuel type"],1]],"sp":["Call dispatch and report: your load number, your status, and a problem (a flat tire) that will delay you.","Dispetcherga qo'ng'iroq qilib xabar bering: yuk raqamingiz, holatingiz va sizni kechiktiradigan muammo (teshilgan shina)."]},
{"d":41,"w":9,"wt":"Pickup & Delivery","t":"At the Warehouse","tu":"Omborda","v":[["Loading dock","Yuklash maydonchasi","Back your trailer into loading dock 7."],["Forklift","Elektrokar (yuk ko'targich)","The forklift will load your pallets."],["Pallet","Pallet (yuk taxtasi)","There are 20 pallets on this order."],["Warehouse","Ombor","Drive to warehouse entrance B."],["Shipping clerk","Yuk jo'natish xodimi","Check in with the shipping clerk first."],["Check in","Ro'yxatdan o'tmoq","Check in at the front office before you park."],["Receiving dock","Qabul qilish maydonchasi","Back into the receiving dock, number 4."],["Shipping dock","Jo'natish maydonchasi","Load from the shipping dock on the east side."],["Staging area","Tayyorlash maydoni","Pallets are ready in the staging area."],["Cross-dock","Ko'chirib yuklash (cross-dock)","This warehouse does cross-dock shipments."],["Inventory","Inventar (ombordagi mol)","Check the inventory count before loading."],["Order picker","Buyurtma terguvchi (ishchi)","The order picker is preparing your load."],["Pallet jack","Pallet ko'targich (qo'lda)","Use a pallet jack to move small loads."],["Barcode scanner","Shtrix-kod skaneri","Scan each pallet with the barcode scanner."],["Safety cones","Xavfsizlik konuslari","Safety cones mark the loading area."],["Yard jockey","Hovli haydovchisi (yard jockey)","The yard jockey moves trailers around the lot."],["Trailer spotter","Tirkama joylashtiruvchi","A trailer spotter will position empty trailers."],["Dock plate","Maydoncha plitasi","The dock plate bridges the gap to the trailer."],["Appointment scheduler","Uchrashuv rejalashtiruvchisi","Book your slot with the appointment scheduler."],["Load number confirmation","Yuk raqamini tasdiqlash","Confirm the load number confirmation at check-in."]],"dl":[["Shipping clerk","Hi, do you have an appointment?","Salom, sizda uchrashuv belgilanganmi?"],["Driver","Yes, 2 PM for load number 8834.","Ha, soat 14:00 ga, 8834-raqamli yuk uchun."],["Shipping clerk","Great, check in here, then back into dock 7.","Ajoyib, shu yerdan ro'yxatdan o'ting, keyin 7-maydonchaga orqasi bilan kiring."],["Driver","Understood. Will a forklift load the pallets?","Tushundim. Palletlarni elektrokar yuklaydimi?"],["Shipping clerk","Yes, someone will be right with you.","Ha, hozir kimdir kelib yordam beradi."]],"g":["'Back into' the dock","'Back into dock 7' means reverse your trailer into the space. This phrasal verb is essential at every warehouse."],"qz":[["Who usually loads pallets onto your trailer?",["The driver alone","A forklift operator","The dispatcher","The police"],1],["'Back into dock 7' means:",["Drive forward into dock 7","Reverse your trailer into dock 7","Park far from dock 7","Skip dock 7"],1],["Where should you go first when you arrive at a warehouse?",["Straight to the dock","Check in with the shipping clerk","Leave the truck running","Take a nap"],1],["A 'pallet' is used to:",["Fuel the truck","Hold and stack cargo","Weigh the truck","Clean the trailer"],1]],"sp":["Describe the process of arriving at a warehouse, checking in, and backing into a dock.","Omborga kelish, ro'yxatdan o'tish va maydonchaga orqasi bilan kirish jarayonini tasvirlab bering."]},
{"d":42,"w":9,"wt":"Pickup & Delivery","t":"Paperwork — Bill of Lading","tu":"Hujjatlar — Yuk Hujjati (BOL)","v":[["Bill of lading (BOL)","Yuk hujjati","Sign the bill of lading after loading."],["Signature","Imzo","I need your signature here."],["Seal number","Plomba raqami","Write down the seal number before you leave."],["Piece count","Yuk birliklari soni","Confirm the piece count matches the BOL."],["Damaged goods","Shikastlangan yuk","Note any damaged goods on the BOL."],["Consignee / Shipper","Qabul qiluvchi / Jo'natuvchi","The consignee will receive the goods; the shipper sent them."],["Freight class","Yuk sinfi","This freight class affects the shipping cost."],["NMFC code","NMFC kodi","The NMFC code classifies the type of freight."],["Weight certificate","Og'irlik sertifikati","Attach the weight certificate to the paperwork."],["Hazmat placard","Xavfli yuk belgisi (plakard)","Display the correct hazmat placard on the trailer."],["Straight bill of lading","Oddiy yuk hujjati","A straight bill of lading has one shipper and one receiver."],["Proof of delivery","Yetkazib berish isboti","Get proof of delivery signed at drop-off."],["Exception noted","Istisno qayd etildi","'Exception noted' means damage was written down."],["Refused shipment","Rad etilgan jo'natma","The customer marked it as a refused shipment."],["Short shipment","Kam yetkazilgan yuk","Report a short shipment to dispatch right away."],["Claim form","Da'vo shakli","Fill out a claim form for the damaged goods."],["Insurance rider","Sug'urta qo'shimchasi","This load has an extra insurance rider."],["Freight charge","Yuk tashish narxi","The freight charge is listed on the invoice."],["Delivery receipt","Yetkazib berish cheki","Keep a copy of the delivery receipt."],["Load count","Yuk soni","Verify the load count matches the paperwork."]],"dl":[["Clerk","Here is the bill of lading. Please check the piece count.","Mana yuk hujjati. Iltimos, yuk birliklari sonini tekshiring."],["Driver","I count 24 pallets. The BOL says 24 too — that matches.","24 ta pallet sanadim. BOL ham 24 deydi — mos keladi."],["Clerk","Good. Please sign here, and note the seal number: 445920.","Yaxshi. Shu yerga imzo qo'ying va plomba raqamini yozib qo'ying: 445920."],["Driver","Signed. I also see one pallet with a torn box — should I note that?","Imzoladim. Bitta pallet қутиси йиртилганини кўраяпман — buni belgilashim kerakmi?"],["Clerk","Yes, please write 'damaged goods' next to that item.","Ha, iltimos o'sha buyum yoniga 'shikastlangan yuk' deb yozing."]],"g":["Checking and confirming","Use 'matches' and 'confirm' when checking paperwork: 'The count matches the BOL. Please confirm the seal number.'"],"qz":[["A 'bill of lading' is a document that:",["Shows your driving hours","Lists the cargo details and must be signed","Is your license","Is a weigh station receipt"],1],["If you find damaged goods, you should:",["Say nothing","Note it on the BOL","Refuse the load always","Throw it away"],1],["The 'seal number' is important because it:",["Shows the fuel level","Proves the trailer wasn't opened during transit","Shows the weight","Is your ID number"],1],["The 'consignee' is the person who:",["Sends the goods","Receives the goods","Drives the truck","Inspects the truck"],1]],"sp":["Explain what you check and do with the bill of lading before leaving a warehouse.","Ombordan chiqishdan oldin yuk hujjati (BOL) bilan nimalarni tekshirishingiz va bajarishingizni tushuntiring."]},
{"d":43,"w":9,"wt":"Pickup & Delivery","t":"Loading & Unloading","tu":"Yuklash va Tushirish","v":[["Load / Unload","Yuklamoq / Tushirmoq","We need to unload before 5 PM."],["Secure the load","Yukni mahkamlamoq","Secure the load with straps before driving."],["Strap down","Kamar bilan mahkamlamoq","Strap down the cargo tightly."],["Tarp","Bryzent bilan yopmoq","Tarp the load if it might rain."],["Lumper","Yuk tushiruvchi (yollangan ishchi)","We hired a lumper to unload the trailer."],["Detention","Kutish vaqti (jarima bilan)","We're in detention — the dock is behind schedule."],["Blocking and bracing","Mahkamlash va tirash","Use blocking and bracing to stop the load from moving."],["Load bars","Yuk to'siqlari","Place load bars between rows of pallets."],["Chock the wheels","G'ildiraklarga tirgovuch qo'yish","Chock the wheels before you start unloading."],["Dock bumper","Maydoncha bamperi","The trailer rests against the dock bumper."],["Load plan","Yuklash rejasi","Follow the load plan for correct weight balance."],["Center of gravity","Og'irlik markazi","Keep the center of gravity low and centered."],["Fragile items","Nozik buyumlar","Mark fragile items clearly on the boxes."],["Stackable","Ustma-ust qo'yish mumkin","These boxes are stackable up to three high."],["Non-stackable","Ustma-ust qo'yib bo'lmaydigan","This pallet is non-stackable — handle with care."],["Hazard label","Xavf belgisi","Every hazmat box needs a hazard label."],["Loading sequence","Yuklash tartibi","Follow the correct loading sequence."],["Unload time estimate","Tushirish vaqti taxmini","What's the unload time estimate today?"],["Weight ticket copy","Og'irlik cheki nusxasi","Keep a weight ticket copy for your records."],["Damage claim","Shikastlanish da'vosi","File a damage claim if goods arrive broken."]],"dl":[["Dock worker","We're ready to unload your trailer now.","Endi tirkamangizni tushirishga tayyormiz."],["Driver","Great. Do you need me to open the doors?","Ajoyib. Eshiklarini men ochishim kerakmi?"],["Dock worker","Yes, please. We'll use a lumper to unload quickly.","Ha, iltimos. Tez tushirish uchun yollangan ishchidan foydalanamiz."],["Driver","Thanks. After you unload, I need my BOL signed.","Rahmat. Tushirib bo'lgach, BOL hujjatimga imzo qo'yishingiz kerak."],["Dock worker","No problem, it will take about 45 minutes.","Muammo yo'q, bu taxminan 45 daqiqa vaqt oladi."]],"g":["Time estimates","'It will take about 45 minutes' — use 'will take about + time' to estimate duration, common when discussing loading/unloading times."],"qz":[["'Secure the load' means to:",["Weigh the load","Fasten it so it doesn't move","Photograph it","Sell it"],1],["A 'lumper' is a person who:",["Drives the truck","Is hired to load/unload cargo","Inspects trucks","Fixes engines"],1],["Why would you 'tarp' a load?",["To make it heavier","To protect it from rain","To weigh it","To hide it from police"],1],["'Detention' at a dock means:",["Being arrested","Waiting longer than scheduled to load/unload","A type of trailer","A speeding fine"],1]],"sp":["Describe how you secure and tarp a load before starting a trip.","Safarni boshlashdan oldin yukni qanday mahkamlashingiz va bryzent bilan yopishingizni tasvirlang."]},
{"d":44,"w":9,"wt":"Pickup & Delivery","t":"Customer Service Interactions","tu":"Mijozlar Bilan Muloqot","v":[["Appointment window","Uchrashuv vaqt oralig'i","Your appointment window is 1-3 PM."],["Late fee","Kechikish jarimasi","There may be a late fee for missing the window."],["Reschedule","Qayta rejalashtirmoq","Can we reschedule for tomorrow morning?"],["Complaint","Shikoyat","The customer has a complaint about the delay."],["Apologize","Uzr so'ramoq","I apologize for the delay."],["Resolve","Hal qilmoq","Let's resolve this issue quickly."],["Point of contact","Aloqa vakili","Who is the point of contact at the warehouse?"],["Escalate a complaint","Shikoyatni yuqoriga ko'tarish","I had to escalate a complaint to the manager."],["Service level agreement","Xizmat darajasi shartnomasi","This customer has a strict service level agreement."],["On-time delivery","O'z vaqtida yetkazib berish","On-time delivery keeps customers happy."],["Delivery confirmation","Yetkazib berish tasdig'i","Send the delivery confirmation to dispatch."],["Signature required","Imzo talab qilinadi","This delivery has 'signature required.'"],["Special instructions","Maxsus ko'rsatmalar","Read the special instructions before delivery."],["Gate code","Darvoza kodi","The customer gave us a gate code."],["Dock hours","Maydoncha ish soatlari","Check the dock hours before you arrive."],["Holiday schedule","Bayram jadvali","The warehouse follows a holiday schedule."],["Customer portal","Mijoz portali","Track your delivery on the customer portal."],["Feedback survey","Fikr-mulohaza so'rovnomasi","The customer sent a short feedback survey."],["Repeat customer","Doimiy mijoz","We want to keep this repeat customer happy."],["Professional tone","Professional ohang","Always keep a professional tone with customers."]],"dl":[["Customer","You are two hours late! Our window was 1-3 PM.","Siz ikki soat kechikdingiz! Bizning vaqt oralig'imiz 1-3 edi."],["Driver","I sincerely apologize for the delay. There was heavy traffic on the highway.","Kechikish uchun chin dildan uzr so'rayman. Shosseда qattiq tirbandlik bor edi."],["Customer","Okay, I understand. Can you unload now?","Xo'p, tushunaman. Hozir tushira olasizmi?"],["Driver","Yes, I'm ready right now. Let's resolve this quickly.","Ha, hozir tayyorman. Buni tezda hal qilaylik."],["Customer","Thank you for being professional about it.","Bu masalada professional bo'lganingiz uchun rahmat."]],"g":["Apologizing professionally","'I apologize for the delay' is more professional than 'I'm sorry.' Add a brief reason: 'due to heavy traffic' — but don't over-explain."],"qz":[["If you are late, a professional response is to:",["Argue with the customer","Apologize and explain briefly","Say nothing","Leave immediately"],1],["An 'appointment window' is:",["Your lunch break","The time range you're expected to arrive","A weigh station time","A break time"],1],["Missing your appointment window might result in a:",["Bonus","Late fee","Free load","Vacation day"],1],["'Resolve an issue' means to:",["Ignore it","Fix/settle it","Make it worse","Report it to police"],1]],"sp":["Roleplay: you arrive late to a delivery. Apologize to the customer and explain professionally.","Rolli o'yin: yetkazib berishga kech qoldingiz. Mijozdan uzr so'rang va professional tarzda tushuntiring."]},
{"d":45,"w":9,"wt":"Pickup & Delivery","rev":true,"t":"Week 9 Review — Delivery Day Roleplay","tu":"9-hafta Takrorlash — Yetkazib Berish Kuni Rolli O'yini","qz":[["Who usually loads pallets with a forklift?",["The driver","A warehouse worker","The dispatcher","The customer"],1],["'Back into the dock' means to:",["Drive forward","Reverse the trailer in","Park far away","Skip the dock"],1],["A bill of lading must be:",["Ignored","Signed and checked","Thrown away","Only for hazmat loads"],1],["The 'seal number' proves:",["Fuel level","The trailer wasn't opened in transit","Speed","Weight"],1],["A 'lumper' is hired to:",["Drive the truck","Load/unload cargo","Fix the engine","Inspect the brakes"],1],["'Detention time' occurs when you:",["Wait longer than scheduled at a dock","Speed on the highway","Get a ticket","Refuel"],0],["If you're late for a delivery, you should:",["Ignore the customer","Apologize professionally","Argue","Leave without delivering"],1],["An 'appointment window' refers to:",["Your break time","The scheduled arrival time range","Your sleep schedule","Fuel stop time"],1]],"sp":["Full roleplay: arrive at a warehouse, check in, handle the paperwork, and deal with a customer complaint about being late.","To'liq rolli o'yin: omborga kelib, ro'yxatdan o'ting, hujjatlar bilan ishlang va kechikish haqidagi mijoz shikoyati bilan shug'ullaning."]},
{"d":46,"w":10,"wt":"Breakdowns & Emergencies","t":"Mechanical Problems","tu":"Texnik Muammolar","v":[["Breakdown","Buzilish","I had a breakdown on the highway."],["Flat tire","Teshilgan shina","I have a flat tire on the trailer."],["Dead battery","O'lgan akkumulyator","My battery is dead, I can't start the truck."],["Overheating","Qizib ketish","The engine is overheating."],["Check engine light","Dvigatel nazorat chirog'i","The check engine light just came on."],["Won't start / Stalled","Yurmayapti / To'xtab qoldi","The truck won't start this morning."],["Transmission slipping","Uzatma qutisi sirg'anishi","The transmission is slipping when I accelerate."],["Brake fade","Tormoz zaiflashuvi","I noticed brake fade going down the mountain."],["Air leak","Havo oqishi","There's an air leak in the brake line."],["Fuel leak","Yoqilg'i oqishi","I see a fuel leak under the tank."],["Coolant leak","Sovutish suyuqligi oqishi","There's a coolant leak near the radiator."],["Belt squeal","Kamar chiyillashi","I hear a belt squeal when I start the engine."],["Electrical short","Elektr qisqa tutashuvi","There might be an electrical short in the wiring."],["Warning buzzer","Ogohlantiruvchi signal","The warning buzzer went off suddenly."],["Warning icon","Ogohlantiruvchi belgi","A warning icon lit up on the dashboard."],["Low oil pressure","Past moy bosimi","The gauge shows low oil pressure."],["Exhaust smoke","Chiqindi gaz tutuni","Black exhaust smoke usually means an engine problem."],["Clutch problem","Klyuch muammosi","I'm having a clutch problem shifting gears."],["Steering issue","Rul muammosi","There's a steering issue, it feels loose."],["Suspension noise","Osma tizim shovqini","I hear a suspension noise over bumps."]],"dl":[["Driver","My check engine light just came on and the engine feels like it's overheating.","Dvigatel nazorat chirog'i endigina yondi va dvigatel qizib ketayotganga o'xshaydi."],["Roadside support","Pull over safely and turn off the engine. Where are you located?","Xavfsiz joyga to'xtang va dvigatelni o'chiring. Qayerda joylashgansiz?"],["Driver","I'm on I-70, mile marker 112, eastbound.","Men I-70 da, 112-milya belgisida, sharqqa qarab ketayapman."],["Roadside support","Got it. A technician will be there within an hour.","Tushundim. Texnik xodim bir soat ichida yetib boradi."]],"g":["'Feels like' for symptoms","Describe symptoms with 'feels like' or 'sounds like': 'The engine feels like it's overheating. It sounds like a flat tire.'"],"qz":[["If the check engine light comes on, you should:",["Ignore it","Pull over safely and check the situation","Drive faster","Turn off the radio"],1],["A 'dead battery' means:",["The truck won't start","The truck has no fuel","The tires are flat","The brakes failed"],0],["'Overheating' refers to:",["The engine getting too hot","The cab getting cold","The tires losing air","The trailer catching fire"],0],["When reporting a breakdown, you should give your:",["Name only","Exact location (highway and mile marker)","Truck color","Fuel level"],1]],"sp":["Report a breakdown to roadside assistance: describe the problem and your exact location.","Yordam xizmatiga buzilish haqida xabar bering: muammoni va aniq joylashuvingizni tasvirlab bering."]},
{"d":47,"w":10,"wt":"Breakdowns & Emergencies","t":"Roadside Assistance & Repairs","tu":"Yo'lda Yordam va Ta'mirlash","v":[["Tow truck","Evakuator","A tow truck is coming to help."],["Mechanic","Mexanik","The mechanic will check the engine."],["Repair shop","Ta'mirlash ustaxonasi","We'll take it to the nearest repair shop."],["Spare parts","Ehtiyot qismlar","We need spare parts for this repair."],["Estimate","Taxminiy narx","Can you give me an estimate for the repair?"],["Downtime","To'xtab qolish vaqti","This breakdown caused two days of downtime."],["Service provider network","Xizmat ko'rsatuvchilar tarmog'i","Find a shop in our service provider network."],["Dispatch fee","Chaqiruv to'lovi","There's a dispatch fee for the tow truck."],["Labor rate","Ish haqi tarifi","The labor rate here is $95 per hour."],["Parts availability","Ehtiyot qismlar mavjudligi","Check parts availability before agreeing to the repair."],["Warranty claim","Kafolat da'vosi","This repair might be covered by a warranty claim."],["Preventive maintenance","Profilaktik texnik xizmat","Preventive maintenance avoids bigger problems later."],["Scheduled service","Rejalashtirilgan xizmat","My truck is due for scheduled service."],["Unscheduled repair","Rejalashtirilmagan ta'mirlash","This is an unscheduled repair — the truck broke down."],["Service history","Xizmat tarixi","Ask the shop to check the service history."],["Fleet maintenance","Avtopark texnik xizmati","Our fleet maintenance team tracks every truck."],["Road call","Yo'lda chaqiruv","This is my second road call this month."],["Mobile mechanic","Ko'chma mexanik","A mobile mechanic can come to your location."],["Service invoice","Xizmat hisob-fakturasi","Keep the service invoice for reimbursement."],["Payment method","To'lov usuli","What payment method do you accept?"]],"dl":[["Mechanic","I checked the engine. You need a new alternator.","Dvigatelni tekshirdim. Sizga yangi generator kerak."],["Driver","Do you have the spare parts here, or do we need to order them?","Ehtiyot qismlar shu yerda bormi, yoki buyurtma qilishimiz kerakmi?"],["Mechanic","We have it in stock. It'll take about 2 hours.","Bizda mavjud. Bu taxminan 2 soat vaqt oladi."],["Driver","Can you give me an estimate for the total cost?","Umumiy narx uchun taxminiy summani ayta olasizmi?"],["Mechanic","About $450 including labor.","Ish haqi bilan taxminan $450."]],"g":["Asking for cost: 'Can you give me an estimate?'","This is the standard professional way to ask about repair cost before agreeing: 'Can you give me an estimate for the repair?'"],"qz":[["A 'tow truck' is called when:",["You need fuel","Your truck can't be driven and needs to be moved","You need a wash","You're at a weigh station"],1],["'Spare parts' are:",["Extra tools","Replacement parts for repairs","Old tires","Fuel containers"],1],["'Downtime' refers to:",["Extra driving time","Time when the truck isn't working/earning","Rest breaks","Loading time"],1],["Before agreeing to a repair, you should ask for a(n):",["Discount","Estimate","New truck","Permit"],1]],"sp":["Talk to a mechanic: describe a problem with your truck and ask for a repair estimate.","Mexanik bilan gaplashing: yuk mashinangizdagi muammoni tasvirlab, ta'mirlash uchun taxminiy narx so'rang."]},
{"d":48,"w":10,"wt":"Breakdowns & Emergencies","t":"Accidents & Emergencies","tu":"Baxtsiz Hodisalar va Favqulodda Holatlar","v":[["Accident","Avariya / Baxtsiz hodisa","There was an accident ahead on the highway."],["Injury","Jarohat","No injuries were reported in the accident."],["Call 911","911 ga qo'ng'iroq qilmoq","Call 911 immediately if someone is hurt."],["Ambulance","Tez yordam mashinasi","An ambulance is on the way."],["Insurance claim","Sug'urta da'vosi","File an insurance claim after the accident."],["Police report","Politsiya hisoboti","You'll need a police report for insurance."],["Fender bender","Kichik avariya (yengil)","It was just a small fender bender, no injuries."],["Jackknife","Qaychisimon burilib qolish","The trailer began to jackknife on the ice."],["Rollover","Ag'darilib ketish","A rollover accident closed the highway."],["Rear-end collision","Orqadan urilib qolish","I was in a rear-end collision at the light."],["Property damage","Mulkka yetkazilgan zarar","There was property damage to a guardrail."],["Bodily injury","Jismoniy jarohat","Thankfully, there was no bodily injury."],["Fault determination","Aybni aniqlash","The police will make a fault determination."],["Dash cam footage","Panel kamerasi yozuvi","The dash cam footage shows what happened."],["Skid marks","G'ildirak izlari (tormozlash)","There were long skid marks on the road."],["Debris field","Sochilgan qoldiqlar maydoni","Watch for a debris field near the crash."],["Traffic control","Trafikni boshqarish","Police set up traffic control after the accident."],["Tow away","Evakuatsiya qilish","The damaged truck was towed away."],["Vehicle recovery","Transport vositasini qutqarish","A recovery truck handled the vehicle recovery."],["Accident scene photos","Baxtsiz hodisa joyidagi suratlar","Take accident scene photos for the report."]],"dl":[["Driver","I was just in an accident. No one is injured, but there's damage to my trailer.","Men hozirgina avariyaga uchradim. Hech kim jarohatlanmadi, lekin tirkamamda shikastlanish bor."],["Dispatcher","Are you safe right now? Did you call 911?","Hozir xavfsizmisiz? 911 ga qo'ng'iroq qildingizmi?"],["Driver","Yes, I'm safe, and I already called 911. They're sending an officer for a police report.","Ha, xavfsizman, va allaqachon 911 ga qo'ng'iroq qildim. Politsiya hisoboti uchun ofitser yuborishmoqda."],["Dispatcher","Good. Don't move the truck until the officer arrives. I'll start the insurance claim.","Yaxshi. Ofitser kelguncha mashinani surmang. Men sug'urta da'vosini boshlayman."]],"g":["Emergency reporting order","In an emergency: 1) Check for injuries, 2) Call 911 if needed, 3) Report to dispatch, 4) Wait for police, 5) File an insurance claim."],"qz":[["In an accident, your first priority is:",["Calling dispatch","Checking for injuries and safety","Taking photos","Moving the truck"],1],["When should you call 911?",["Only for minor scratches","If someone is injured or in danger","Never, call dispatch instead","Only during business hours"],1],["A 'police report' is needed for:",["Your logbook","Insurance claims","Weigh stations","Fuel receipts"],1],["After an accident, you should generally:",["Move the truck immediately","Wait for police before moving the truck","Leave the scene","Argue with the other driver"],1]],"sp":["Explain the correct steps to take immediately after a truck accident.","Yuk mashinasi avariyasidan so'ng darhol bajarilishi kerak bo'lgan to'g'ri qadamlarni tushuntiring."]},
{"d":49,"w":10,"wt":"Breakdowns & Emergencies","t":"Emergency Phrases & 911 Calls","tu":"Favqulodda Iboralar va 911 ga Qo'ng'iroqlar","v":[["Emergency","Favqulodda holat","This is an emergency, I need help now."],["My location is...","Mening joylashuvim...","My location is Interstate 40, mile marker 55."],["Someone is injured","Kimdir jarohatlangan","Someone is injured, please send an ambulance."],["I need help immediately","Menga hozir yordam kerak","I need help immediately, there's been an accident."],["Stay calm","Xotirjam bo'ling","Stay calm, help is on the way."],["Stay on the line","Aloqada qoling","Please stay on the line with me."],["Fire on board","Yong'in (mashinada)","There's a fire on board, I need help now!"],["Hazmat spill","Xavfli yuk to'kilishi","There's a hazmat spill, please send hazmat response."],["Evacuate the area","Hududni bo'shatish","Evacuate the area immediately, it's dangerous."],["Medical emergency","Tibbiy favqulodda holat","This is a medical emergency, send an ambulance."],["Chest pain","Ko'krak og'rig'i","The other driver has chest pain."],["Not breathing","Nafas olmayapti","He is not breathing, please hurry."],["Unconscious","Hushidan ketgan","The driver is unconscious in the vehicle."],["Bleeding heavily","Kuchli qon ketishi","There is bleeding heavily from the arm."],["Trapped","Qopilib qolgan","Someone is trapped inside the vehicle."],["Send backup","Qo'shimcha yordam yuboring","Please send backup, this is serious."],["Cross street","Kesishuvchi ko'cha","The cross street is Highway 12."],["Exit number reference","Chiqish raqami ma'lumoti","I'm near exit number 42 for reference."],["Stay on scene","Voqea joyida qoling","Stay on scene until help arrives."],["Hazard lights on","Avariya chiroqlarini yoqish","I turned my hazard lights on for safety."]],"dl":[["911 Operator","911, what's your emergency?","911, favqulodda holatingiz nima?"],["Driver","This is an emergency. I'm in a truck accident on Interstate 40, mile marker 55.","Bu favqulodda holat. Men Interstate 40 da, 55-milya belgisida avariyaga uchradim."],["911 Operator","Is anyone injured?","Kimdir jarohatlanganmi?"],["Driver","Yes, someone is injured. I need help immediately.","Ha, kimdir jarohatlangan. Menga hozir yordam kerak."],["911 Operator","Stay calm, help is on the way. Please stay on the line with me.","Xotirjam bo'ling, yordam yo'lda. Iltimos, men bilan aloqada qoling."]],"g":["Giving your location clearly","Always give: highway number + direction + mile marker. Example: 'Interstate 40, eastbound, mile marker 55.' This helps emergency services find you fast."],"qz":[["When you call 911, the operator will first ask:",["Your name","What's your emergency","Your truck's color","Your company name"],1],["The best way to give your location is:",["'Somewhere on the highway'","Highway number + direction + mile marker","Just the city name","Your phone number"],1],["'Stay on the line' means:",["Hang up quickly","Don't hang up, keep talking","Drive away","Call someone else"],1],["If someone is injured, you should tell the operator:",["Nothing, just hang up","'Someone is injured'","Only your name","The weather"],1]],"sp":["Practice calling 911: report an emergency, give your exact location, and say if anyone is injured.","911 ga qo'ng'iroq qilishni mashq qiling: favqulodda holat haqida xabar bering, aniq joylashuvingizni ayting va kimdir jarohatlanganmi-yo'qmi ayting."]},
{"d":50,"w":10,"wt":"Breakdowns & Emergencies","rev":true,"t":"Week 10 Review — Emergency Response Test","tu":"10-hafta Takrorlash — Favqulodda Vaziyatga Javob Sinovi","qz":[["If the check engine light comes on, you should:",["Ignore it and keep driving fast","Pull over safely and assess it","Turn off the radio","Speed up to the next exit"],1],["A tow truck is needed when:",["You need fuel","Your truck can't be driven","You want a wash","You're bored"],1],["Before agreeing to a repair, always ask for a(n):",["Discount code","Estimate","New engine","Permit"],1],["In an accident, your first priority is:",["Taking photos","Checking for injuries and safety","Calling your family","Moving the truck"],1],["A police report after an accident is used for:",["Insurance claims","Your logbook only","Weigh stations","Fuel discounts"],0],["When calling 911, you should clearly give your:",["Name only","Location (highway + mile marker)","Truck color","Company logo"],1],["'Stay on the line' means:",["Hang up","Keep talking, don't hang up","Call someone else","Drive faster"],1],["'Downtime' means:",["Extra pay","Time the truck isn't earning due to repairs","Rest breaks","Fueling time"],1]],"sp":["Roleplay a full emergency: your truck breaks down, you call roadside assistance, then report it to dispatch.","To'liq favqulodda vaziyatni o'ynang: yuk mashinangiz buzildi, yordam xizmatiga qo'ng'iroq qilasiz, keyin dispetcherga xabar berasiz."]},
{"d":51,"w":11,"wt":"Trucking Life & Facilities","t":"Truck Stops & Fuel","tu":"Yuk Mashinalari Bekatlari va Yoqilg'i","v":[["Fuel island","Yoqilg'i quyish joyi","Pull up to fuel island number 3."],["Diesel","Dizel yoqilg'isi","Fill it up with diesel, please."],["DEF (Diesel Exhaust Fluid)","DEF suyuqligi","Don't forget to add DEF too."],["Fuel card","Yoqilg'i kartasi","Pay with your company fuel card."],["Receipt","Chek","Keep the receipt for your records."],["Shower / Lounge","Dush / Dam olish xonasi","There's a free shower for drivers."],["Price per gallon","Gallon narxi","Check the price per gallon before you fuel up."],["Fuel surcharge","Yoqilg'i ustama to'lovi","The company charges a fuel surcharge to customers."],["Fuel efficiency","Yoqilg'i samaradorligi","Smooth driving improves fuel efficiency."],["Idle time cost","Bo'sh ishlash xarajati","Idle time cost adds up over a year."],["Fuel tax","Yoqilg'i solig'i","Fuel tax varies from state to state."],["Reefer fuel","Sovutgich yoqilg'isi","Don't forget to check the reefer fuel too."],["Fuel theft","Yoqilg'i o'g'irlanishi","Lock your fuel cap to prevent fuel theft."],["Locking fuel cap","Qulflanadigan yoqilg'i qopqog'i","Install a locking fuel cap for security."],["Fuel gauge","Yoqilg'i o'lchagichi","Watch the fuel gauge on long stretches."],["Range","Masofa zaxirasi (yoqilg'i bilan)","My range is about 1,200 miles on a full tank."],["Fill level","To'ldirish darajasi","Check the fill level before you leave."],["Card decline","Karta rad etilishi","My fuel card had a decline — call the help line."],["Fuel receipt scan","Yoqilg'i chekini skanerlash","Do a fuel receipt scan for your expense report."],["Bulk fuel discount","Ko'p miqdordagi yoqilg'i chegirmasi","We get a bulk fuel discount at this chain."]],"dl":[["Driver","I need to fuel up. Which island is open?","Yoqilg'i quyishim kerak. Qaysi joy bo'sh?"],["Attendant","Island 5 is open. Are you paying with a fuel card?","5-joy bo'sh. Yoqilg'i kartasi bilan to'laysizmi?"],["Driver","Yes, company card. And I need DEF too.","Ha, kompaniya kartasi. Menga DEF ham kerak."],["Attendant","No problem, it's right next to the diesel pump. Don't forget your receipt.","Muammo yo'q, u dizel насоси yonida. Chekingizni unutmang."],["Driver","Thanks. Is the shower free for drivers?","Rahmat. Haydovchilar uchun dush bepulmi?"],["Attendant","Yes, with a fuel purchase.","Ha, yoqilg'i sotib olganingizda."]],"g":["'Fill it up'","'Fill it up, please' is the common phrase to ask for a full tank. 'It' refers to the fuel tank."],"qz":[["What does DEF stand for in trucking?",["Direct Engine Fuel","Diesel Exhaust Fluid","Daily Engine Fill","Driver Emergency Form"],1],["You should keep your fuel receipt for:",["Fun","Your records","The police","Nothing, throw it away"],1],["Many truck stops offer free showers when you:",["Ask nicely","Purchase fuel","Show your CDL","Wait 2 hours"],1],["'Fill it up' means:",["Empty the tank","Fill the tank completely","Check the oil","Wash the truck"],1]],"sp":["Order fuel and DEF at a truck stop, and ask about the shower facilities.","Yuk mashinalari bekatida yoqilg'i va DEF buyurtma qiling hamda dush xonalari haqida so'rang."]},
{"d":52,"w":11,"wt":"Trucking Life & Facilities","t":"Food & Rest Areas","tu":"Ovqat va Dam Olish Joylari","v":[["Menu","Menyu","Can I see the menu, please?"],["Order","Buyurtma qilmoq","I'd like to order a coffee and a sandwich."],["To go","Olib ketish uchun","Can I get this to go?"],["Restroom","Hojatxona","Where is the restroom, please?"],["Vending machine","Avtomat (mashina)","There's a vending machine by the entrance."],["Drive-thru","Haydab o'tib buyurtma olish","Let's use the drive-thru, I don't want to park."],["Combo meal","Kombinatsiyalangan taom","I'll have the combo meal with a coffee."],["Value menu","Arzon menyu","The value menu has cheaper options."],["Appetizer","Old taom (zakuska)","Would you like an appetizer with that?"],["Beverage refill","Ichimlik to'ldirish","Is the beverage refill free here?"],["Tip","Choy puli (ang'am)","Don't forget to leave a tip."],["To-go container","Olib ketish qutisi","Can I get a to-go container for this?"],["Microwave","Mikroto'lqinli pech","There's a microwave in the driver's lounge."],["Truck stop restaurant","Yuk mashinalari bekati restorani","Let's eat at the truck stop restaurant."],["Buffet","Bufet","This truck stop has a buffet for $12."],["Food court","Ovqatlanish maydoni","There's a food court with several choices."],["Snack bar","Yengil taomlar do'koni","Grab some chips at the snack bar."],["Ice machine","Muz mashinasi","The ice machine is near the entrance."],["Water fountain","Suv favvorasi (ichish uchun)","Fill your bottle at the water fountain."],["Seating area","O'tirish joyi","The seating area is open 24 hours."]],"dl":[["Driver","Hi, can I see the menu, please?","Salom, menyuni ko'rsam bo'ladimi?"],["Server","Sure, here you go. What can I get you?","Albatta, mana. Sizga nima buyuray?"],["Driver","I'd like a coffee and a sandwich, to go, please.","Menga kofe va sendvich, olib ketish uchun, iltimos."],["Server","No problem. Anything else? We also have a restroom in the back.","Muammo yo'q. Yana narsa kerakmi? Orqada hojatxona ham bor."],["Driver","No, that's all. Thank you.","Yo'q, shu yetarli. Rahmat."]],"g":["Ordering food politely","'I'd like...' is more polite than 'Give me...'. 'I'd like a coffee, please. I'd like this to go.'"],"qz":[["'To go' means you want your food:",["To eat there","To take with you","For free","Delivered home"],1],["A polite way to order is:",["Give me a coffee","I'd like a coffee, please","Coffee now","I want coffee"],1],["A 'vending machine' is used to:",["Wash clothes","Buy snacks/drinks automatically","Get fuel","Print receipts"],1],["A 'drive-thru' lets you:",["Park and walk in","Order without leaving your vehicle","Fuel your truck","Take a shower"],1]],"sp":["Order food at a restaurant: ask for the menu and order something to go.","Restoranda ovqat buyurtma qiling: menyuni so'rang va olib ketish uchun biror narsa buyurtma qiling."]},
{"d":53,"w":11,"wt":"Trucking Life & Facilities","t":"Banking, Money & Paychecks","tu":"Bank, Pul va Ish Haqi","v":[["Direct deposit","To'g'ridan-to'g'ri o'tkazma","My paycheck comes by direct deposit."],["Paycheck","Ish haqi (chek)","I get my paycheck every Friday."],["Per diem","Kunlik xarajat puli","Per diem covers meals on the road."],["Deduction","Ushlab qolish (soliq va h.k.)","Taxes are a deduction from your pay."],["Bank account","Bank hisob raqami","Set up a bank account for direct deposit."],["Cash advance","Naqd pul avansi","I need a cash advance for fuel."],["Settlement statement","Hisob-kitob varag'i","Review your settlement statement every week."],["Gross pay","Umumiy ish haqi","Gross pay is the amount before deductions."],["Net pay","Sof ish haqi","Net pay is what actually goes to your account."],["Mileage pay","Milya bo'yicha to'lov","I get mileage pay of 55 cents per mile."],["Percentage pay","Foiz bo'yicha to'lov","Some carriers offer percentage pay instead."],["Safety bonus","Xavfsizlik bonusi","I earned a safety bonus this quarter."],["Fuel bonus","Yoqilg'i bonusi","Good fuel efficiency can earn a fuel bonus."],["Referral bonus","Tavsiya bonusi","Refer a friend and get a referral bonus."],["Escrow account","Depozit hisobi","Some leases require an escrow account."],["Truck payment","Mashina to'lovi","My weekly truck payment is due Friday."],["Lease-purchase","Ijaradan sotib olish","I'm on a lease-purchase program."],["Independent contractor","Mustaqil pudratchi","I work as an independent contractor."],["W-2 vs 1099","W-2 va 1099 solig'i","Ask your accountant about W-2 vs 1099."],["Pay period","To'lov davri","Our pay period runs Monday to Sunday."]],"dl":[["Driver","When do I get my first paycheck?","Birinchi ish haqimni qachon olaman?"],["HR","Every Friday, by direct deposit to your bank account.","Har juma kuni, bank hisob raqamingizga to'g'ridan-to'g'ri o'tkazma orqali."],["Driver","Does the company offer per diem for meals?","Kompaniya ovqat uchun kunlik xarajat puli beradimi?"],["HR","Yes, per diem is included, minus standard deductions like taxes.","Ha, kunlik xarajat puli kiritilgan, soliq kabi standart ushlab qolishlar chiqarilib."],["Driver","Can I get a cash advance if I need fuel before payday?","Agar ish haqigacha yoqilg'i kerak bo'lsa, naqd pul avans ola olamanmi?"]],"g":["Talking about pay","'I get paid every Friday. My pay comes by direct deposit.' Use 'get paid' as a common verb phrase for receiving wages."],"qz":[["'Direct deposit' means your pay goes:",["In cash to your hand","Directly to your bank account","To your dispatcher","Nowhere"],1],["'Per diem' covers:",["Fuel costs","Daily meal/living expenses","Truck repairs","Insurance"],1],["'Deductions' from your paycheck usually include:",["Bonuses","Taxes and other withholdings","Extra pay","Vacation days"],1],["A 'cash advance' is:",["Free money","Money given early, before payday","A type of fine","A bonus"],1]],"sp":["Ask HR about your paycheck schedule, direct deposit, and per diem.","HR bo'limidan ish haqi jadvali, to'g'ridan-to'g'ri o'tkazma va kunlik xarajat puli haqida so'rang."]},
{"d":54,"w":11,"wt":"Trucking Life & Facilities","t":"Health & Medical Checkups","tu":"Sog'liq va Tibbiy Ko'rik","v":[["DOT physical","DOT tibbiy ko'rigi","You need a DOT physical every 2 years."],["Medical card","Tibbiy karta","Keep your medical card in your wallet."],["Blood pressure","Qon bosimi","The doctor will check your blood pressure."],["Doctor's appointment","Shifokor qabuli","I have a doctor's appointment on Monday."],["Pharmacy","Dorixona","Pick up your prescription at the pharmacy."],["Symptoms","Alomatlar","Tell the doctor about your symptoms."],["Sleep apnea","Uyqu apnoesi","Sleep apnea can affect your medical card."],["CPAP machine","CPAP apparati","I use a CPAP machine every night."],["Vision test","Ko'rish testi","The vision test checks both eyes."],["Hearing test","Eshitish testi","You'll also take a hearing test."],["Urine test","Siydik tahlili","A urine test checks your sugar and protein levels."],["Diabetes screening","Diabet tekshiruvi","Diabetes screening is part of the physical."],["Heart condition","Yurak kasalligi","Tell the doctor about any heart condition."],["Medication list","Dori-darmonlar ro'yxati","Bring a medication list to your appointment."],["Waiver","Istisno hujjati (waiver)","You may need a waiver for certain conditions."],["Certificate expiration","Sertifikat muddati tugashi","Watch the certificate expiration date closely."],["Recertification","Qayta sertifikatlash","Schedule your recertification a month early."],["Health insurance","Tibbiy sug'urta","Ask HR about your health insurance options."],["Wellness program","Sog'lomlashtirish dasturi","The company offers a wellness program."],["Annual checkup","Yillik ko'rik","Don't skip your annual checkup."]],"dl":[["Doctor","I'm going to check your blood pressure and vision for your DOT physical.","DOT tibbiy ko'rigi uchun qon bosimingiz va ko'rish qobiliyatingizni tekshiraman."],["Driver","Okay. I've had some back pain lately — should I mention that?","Xo'p. Oxirgi paytlarda bel og'rig'im bor edi — buni aytishim kerakmi?"],["Doctor","Yes, always mention your symptoms. It's important for your health and safety.","Ha, doim alomatlaringizni ayting. Bu sog'ligingiz va xavfsizligingiz uchun muhim."],["Driver","Understood. When will I get my medical card?","Tushundim. Tibbiy kartamni qachon olaman?"],["Doctor","If everything is normal, you'll get it today.","Agar hammasi normal bo'lsa, bugun olasiz."]],"g":["Describing symptoms: 'I've had...'","Use present perfect for ongoing symptoms: 'I've had back pain. I've had a headache for two days.'"],"qz":[["A DOT physical is required:",["Once in your life","Every 2 years (typically)","Every week","Never"],1],["Your 'medical card' proves:",["You paid for insurance","You're physically qualified to drive","You own a truck","You passed the DOT inspection"],1],["If you have symptoms like back pain, you should:",["Hide it from the doctor","Mention it to the doctor","Ignore it forever","Quit driving immediately"],1],["You pick up prescription medicine at the:",["Truck stop","Pharmacy","Weigh station","Dispatch office"],1]],"sp":["Describe a DOT physical exam and what the doctor checks.","DOT tibbiy ko'rigini va shifokor nimalarni tekshirishini tasvirlab bering."]},
{"d":55,"w":11,"wt":"Trucking Life & Facilities","rev":true,"t":"Week 11 Review — Life on the Road Quiz","tu":"11-hafta Takrorlash — Yo'ldagi Hayot Sinovi","qz":[["DEF stands for:",["Diesel Exhaust Fluid","Direct Engine Fuel","Daily Engine Form","Drive Emergency Fluid"],0],["Many truck stops offer free showers when you:",["Wait in line","Purchase fuel","Show ID only","Ask twice"],1],["'To go' at a restaurant means:",["Eat inside","Take your food with you","It's free","Delivery only"],1],["'Direct deposit' sends your pay:",["In cash","To your bank account","To dispatch","Nowhere, it's a myth"],1],["'Per diem' covers:",["Truck repairs","Daily meal expenses","Insurance","Tolls only"],1],["A DOT physical exam is typically required every:",["6 months","2 years","10 years","Never"],1],["Your 'medical card' proves you are:",["Insured","Physically fit to drive","A US citizen","Trained in first aid"],1],["A 'cash advance' means money given:",["As a bonus","Early, before payday","For free","As a fine"],1]],"sp":["Describe a typical day off the road: fueling, eating, and taking care of paperwork or health needs.","Yo'ldan tashqaridagi oddiy kunni tasvirlab bering: yoqilg'i quyish, ovqatlanish va hujjatlar yoki sog'liqqa oid ishlar bilan shug'ullanish."]},
{"d":56,"w":12,"wt":"Career & Advanced Conversation","t":"Job Interviews","tu":"Ish Suhbati","v":[["Experience","Tajriba","I have 3 years of experience driving."],["References","Tavsiyanomalar","I can provide references from my last job."],["Endorsement","Ruxsatnoma qo'shimchasi (CDL)","I have a hazmat endorsement on my CDL."],["Clean record","Toza tarix (huquqbuzarliksiz)","I have a clean driving record."],["Application","Ariza","Please fill out the application form."],["Background check","Ma'lumotlar tekshiruvi","We will run a background check first."],["Cover letter","Muqova xati","Attach a short cover letter with your application."],["Resume","Rezyume","Update your resume with recent experience."],["Salary expectations","Maosh bo'yicha kutishlar","What are your salary expectations?"],["Home time preference","Uyga borish afzalligi","What is your home time preference — weekly?"],["Fleet type","Avtopark turi","What fleet type do you drive — dry van or reefer?"],["Equipment provided","Ta'minlangan jihozlar","New trucks are equipment provided by the company."],["Orientation schedule","Moslashuv jadvali","Orientation schedule starts Monday morning."],["Training program","O'quv dasturi","Our training program lasts two weeks."],["Mentor driver","Murabbiy haydovchi","A mentor driver will ride with you at first."],["Probation period","Sinov muddati","There's a 90-day probation period."],["Sign-on bonus","Ishga kirish bonusi","We offer a $2,000 sign-on bonus."],["Benefits package","Imtiyozlar paketi","Ask about the full benefits package."],["Notice period","Ogohlantirish muddati","Give a two-week notice period when you leave."],["Job offer","Ish taklifi","I accepted the job offer yesterday."]],"dl":[["Interviewer","Tell me about your driving experience.","Haydovchilik tajribangiz haqida gapirib bering."],["Driver","I have 3 years of experience, mostly long-haul dry van. I have a clean driving record.","Menda 3 yillik tajriba bor, asosan uzoq masofali yopiq tirkamada. Toza haydovchilik tarixim bor."],["Interviewer","Do you have any endorsements?","Sizda qo'shimcha ruxsatnomalar bormi?"],["Driver","Yes, I have a hazmat endorsement and a tanker endorsement.","Ha, menda hazmat va sisterna ruxsatnomalari bor."],["Interviewer","Great. We'll need two references and we'll run a background check.","Ajoyib. Bizga ikkita tavsiyanoma kerak bo'ladi va ma'lumotlar tekshiruvini o'tkazamiz."]],"g":["Talking about experience","Use present perfect + 'for': 'I have 3 years of experience. I have been driving for 3 years.' Both are correct in interviews."],"qz":[["A 'hazmat endorsement' allows you to:",["Drive faster","Haul hazardous materials","Skip inspections","Avoid weigh stations"],1],["A 'clean driving record' means:",["No violations","Many accidents","A new license","A washed truck"],0],["'References' in a job interview are:",["Old paychecks","People who can vouch for you","Your family members","Truck parts"],1],["A 'background check' is done to:",["Check your truck","Verify your history and record","Check your fuel level","Weigh your truck"],1]],"sp":["Answer this interview question: 'Tell me about your driving experience and any endorsements you have.'","Ushbu suhbat savoliga javob bering: 'Haydovchilik tajribangiz va qanday ruxsatnomalaringiz borligi haqida gapirib bering.'"]},
{"d":57,"w":12,"wt":"Career & Advanced Conversation","t":"Performance Reviews & Safety Meetings","tu":"Ish Baholash va Xavfsizlik Yig'ilishlari","v":[["Performance","Ish faoliyati","Your performance this quarter was excellent."],["Feedback","Fikr-mulohaza","I have some feedback about your last trip."],["Safety meeting","Xavfsizlik yig'ilishi","All drivers must attend the safety meeting."],["Incident report","Hodisa hisoboti","Fill out an incident report for any near-miss."],["Improvement","Yaxshilanish","There's room for improvement in fuel efficiency."],["Bonus","Bonus (qo'shimcha to'lov)","Safe drivers receive a quarterly bonus."],["KPI","Asosiy ko'rsatkich (KPI)","On-time delivery is an important KPI."],["On-time percentage","O'z vaqtida bajarish foizi","Your on-time percentage is 98 percent."],["Fuel efficiency score","Yoqilg'i samaradorligi bali","Your fuel efficiency score improved this month."],["Accident-free record","Baxtsiz hodisasiz tarix","Keep your accident-free record going."],["Customer rating","Mijoz bahosi","Your customer rating was excellent this trip."],["Peer review","Hamkasblar bahosi","We do a peer review every quarter."],["Goal setting","Maqsad belgilash","Goal setting helps you improve each month."],["Action plan","Harakat rejasi","Let's create an action plan together."],["Recognition award","Tan olish mukofoti","You earned a recognition award this year."],["Driver of the month","Oyning eng yaxshi haydovchisi","Congratulations, you're driver of the month!"],["Coaching session","Murabbiylik mashg'uloti","Join a coaching session to improve your skills."],["Corrective action","Tuzatuvchi chora","We need a corrective action plan for this."],["Follow-up review","Qo'shimcha baholash","We'll have a follow-up review in 30 days."],["Career path","Karyera yo'li","There's a clear career path at this company."]],"dl":[["Manager","Let's review your performance this quarter. Your safety record is excellent.","Bu chorak uchun ish faoliyatingizni ko'rib chiqaylik. Xavfsizlik tarixingiz a'lo darajada."],["Driver","Thank you. I try to drive carefully and follow the HOS rules.","Rahmat. Men ehtiyotkorlik bilan haydashga va HOS qoidalariga rioya qilishga harakat qilaman."],["Manager","I do have some feedback about fuel efficiency — there's room for improvement.","Yoqilg'i samaradorligi bo'yicha fikr-mulohazam bor — yaxshilanish uchun joy bor."],["Driver","Understood, I'll work on smoother acceleration and braking.","Tushundim, tekisroq tezlashtirish va tormozlashda ishlayman."],["Manager","Great. Keep up the safe driving and you'll qualify for the quarterly bonus.","Ajoyib. Xavfsiz haydashda davom eting va choraklik bonusga ega bo'lasiz."]],"g":["Receiving feedback gracefully","Respond to feedback with 'Understood' or 'I'll work on that' — this shows professionalism, even with criticism."],"qz":[["A 'safety meeting' is where drivers:",["Get their paycheck","Discuss safety topics and rules","Fuel their trucks","Wait for dispatch"],1],["'Feedback' from a manager is:",["Always negative","Comments about your performance","A type of fine","A bonus payment"],1],["An 'incident report' should be filed for:",["Every meal break","Accidents or near-misses","Fuel purchases","Vacation requests"],1],["A professional response to feedback is:",["Arguing","'Understood, I'll work on that'","Ignoring it","Quitting"],1]],"sp":["Respond to a manager giving you feedback about improving fuel efficiency.","Yoqilg'i samaradorligini yaxshilash haqida fikr-mulohaza bergan menejerga javob bering."]},
{"d":58,"w":12,"wt":"Career & Advanced Conversation","t":"Advanced Small Talk & Trucking Idioms","tu":"Murakkab Suhbat va Haydovchilik Idiomalari","v":[["Hit the road","Yo'lga chiqmoq","Time to hit the road, see you later!"],["On the clock","Ish vaqtida","I'm on the clock until 8 PM."],["Burning daylight","Vaqtni behuda o'tkazmoq","Let's go, we're burning daylight!"],["Dead-head","Yuksiz haydash","I'm dead-heading back empty today."],["Run hot","Tez haydamoq (shoshilinch)","We need to run hot to make this delivery."],["Keep on trucking","Davom etaveraman (haydashda)","No matter what, keep on trucking!"],["Bobtailing","Bosh qismisiz haydash (tirkamasiz)","I'm bobtailing back to the yard tonight."],["Hammer down","Tezlashtirmoq (jargon)","Hammer down, we need to make this delivery."],["Green light","Ruxsat (norasmiy)","Dispatch gave us the green light to go."],["Behind the wheel","Rul ortida","I've been behind the wheel for six hours."],["Long haul","Uzoq masofali reys","I prefer long haul routes over short ones."],["Short haul","Qisqa masofali reys","Short haul lets me get home every night."],["Road warrior","Yo'l jangchisi (jargon)","He's a real road warrior, driving for 20 years."],["Rig","Mashina (jargon, yuk mashinasi)","Nice rig — is it new?"],["Big rig","Katta yuk mashinasi","That's a beautiful big rig."],["Highway hypnosis","Shosse gipnozi (charchoqdan)","Highway hypnosis happens on long, boring roads."],["Coffee stop","Kofe uchun to'xtash","Let's make a quick coffee stop."],["Shift gears","Tezlikni almashtirmoq (majoziy)","Time to shift gears and change our plan."],["Road rage","Yo'lda g'azab","Stay calm and avoid road rage."],["Stuck in a rut","Bir joyda qotib qolish (majoziy)","I felt stuck in a rut driving the same route."]],"dl":[["Driver A","Ready to hit the road? We're burning daylight.","Yo'lga chiqishga tayyormisiz? Vaqtni behuda o'tkazyapmiz."],["Driver B","Almost. Just finishing my coffee. Are we dead-heading or loaded today?","Deyarli. Kofemni tugataman. Bugun yuksiz haydaymizmi yoki yuklanganmizmi?"],["Driver A","Loaded — and dispatch wants us to run hot, the delivery window is tight.","Yuklanganmiz — va dispetcher bizdan tez haydashimizni xohlaydi, yetkazib berish vaqti tor."],["Driver B","Got it. Well, let's keep on trucking then!","Tushundim. Xo'sh, davom etaylik!"]],"g":["Idioms are informal — use with care","Idioms like 'hit the road' are great for casual talk with other drivers but avoid them with officers, customers, or in formal writing."],"qz":[["'Hit the road' means to:",["Stop driving","Start a trip / leave","Crash the truck","Take a nap"],1],["'We're burning daylight' means:",["It's very sunny","We're wasting time, let's hurry","The lights are broken","It's nighttime"],1],["'Run hot' means to:",["Drive with the heater on","Hurry to meet a deadline","Overheat the engine","Drive slowly"],1],["'On the clock' means you are:",["Off work","Currently working/on duty","Late","Retired"],1]],"sp":["Use 3 trucking idioms in a short conversation with another driver.","Boshqa haydovchi bilan qisqa suhbatda 3 ta haydovchilik idiomasidan foydalaning."]},
{"d":59,"w":12,"wt":"Career & Advanced Conversation","t":"Mock Full Conversation Practice","tu":"To'liq Suhbat Mashqi","v":[["Overall review","Umumiy takrorlash","Today we review vocabulary from the whole course."],["Confidence","Ishonch","Speak with confidence during your inspection."],["Professionalism","Professionallik","Professionalism matters in every conversation."],["Fluency","Ravonlik","Practice improves your fluency."],["Preparedness","Tayyorgarlik","Preparedness helps you handle any situation."],["Real-world scenario","Haqiqiy hayotiy vaziyat","Let's practice a real-world scenario now."],["Confidence booster","Ishonchni oshiruvchi","Practice is a great confidence booster."],["Real-time practice","Real vaqtda mashq","This roleplay is real-time practice."],["Mixed vocabulary","Aralash lug'at","Today mixes vocabulary from the whole course."],["Situational English","Vaziyatga oid ingliz tili","Situational English helps in real conversations."],["Follow-up question","Qo'shimcha savol","Always be ready for a follow-up question."],["Clarify politely","Xushmuomalalik bilan aniqlashtirish","Clarify politely if you don't understand."],["Rephrase","Boshqacha ifodalash","Rephrase your answer if they look confused."],["Summarize","Xulosa qilish","Summarize the conversation at the end."],["Double-check","Qayta tekshirish","Double-check your documents before you leave."],["Wrap up","Yakunlamoq","Let's wrap up this conversation."],["Sign off","Yakunlab xayrlashish","Sign off politely before hanging up."],["Debrief","Xulosa chiqarish (suhbat)","We'll debrief after the roleplay."],["Everyday English","Kundalik ingliz tili","Everyday English is what you'll use most on the job."],["Full conversation","To'liq suhbat","Try to keep up a full conversation in English."]],"dl":[["Officer","License and registration, please. Where are you headed?","Guvohnoma va ro'yxatga olish hujjatini bering. Qayerga ketyapsiz?"],["Driver","Here you go, officer. I'm headed to Denver with a load of electronics.","Mana, ofitser. Men Denverga elektronika yuki bilan ketyapman."],["Officer","How long have you been driving today?","Bugun qancha vaqtdan beri haydayapsiz?"],["Driver","About 6 hours. I have 5 hours left in my 11-hour limit. Here's my ELD log.","Taxminan 6 soat. 11 soatlik chegaramda 5 soat qoldi. Mana mening ELD jurnalim."],["Officer","Everything looks good. Drive safe.","Hammasi yaxshi ko'rinyapti. Xavfsiz haydang."],["Driver","Thank you, officer. Have a good day.","Rahmat, ofitser. Kuningiz xayrli o'tsin."]],"g":["Bringing it all together","By now you can combine greetings, documents, HOS talk, and polite responses in one fluent conversation. This is the goal — natural, confident English."],"qz":[["Combining greetings, documents, and HOS talk shows:",["Confusion","Fluency and preparedness","Nervousness","Poor training"],1],["When an officer asks how long you've been driving, you should answer with:",["A vague answer","A clear time + offer to show your log","Silence","A joke"],1],["Professionalism in conversation means:",["Talking a lot","Being clear, polite, and confident","Speaking very fast","Avoiding eye contact"],1],["The goal of this course is to help you:",["Memorize grammar rules only","Communicate confidently in real trucking situations","Pass a written test only","Learn British English"],1]],"sp":["Full roleplay: combine a DOT stop, document check, and HOS conversation into one smooth interaction.","To'liq rolli o'yin: DOT to'xtatilishi, hujjatlarni tekshirish va HOS suhbatini bitta silliq muloqotga birlashtiring."]},
{"d":60,"w":12,"wt":"Career & Advanced Conversation","rev":true,"t":"FINAL ROAD TEST — Comprehensive Exam","tu":"YAKUNIY YO'L SINOVI — Yakuniy Imtihon","final":true,"qz":[["What is the correct way to answer 'What are you hauling?'",["'I am fine'","'I'm hauling furniture, dry van trailer'","'Yes, officer'","'Phoenix, Arizona'"],1],["The 11-hour rule limits your:",["Rest time","Maximum daily driving time","Fuel usage","Loading time"],1],["At a weigh station, a red light from the bypass system means:",["Continue driving","Pull in for inspection","Turn around","Call dispatch"],1],["A 'bill of lading' should be checked for:",["Fuel type","Piece count and cargo details","Weather","Speed limit"],1],["If you feel drowsy while driving, you should:",["Keep going, you're almost there","Pull over and rest","Turn up the radio","Drink more coffee only"],1],["'10-4' on the CB radio means:",["Emergency","Message received/understood","Turn around","Goodbye forever"],1],["In an accident, your first priority is:",["Taking photos","Checking for injuries and safety","Calling your family","Moving the truck immediately"],1],["A DOT physical exam is required approximately every:",["6 months","2 years","5 years","Never"],1],["'Detention time' happens when you:",["Speed on the highway","Wait longer than scheduled to load/unload","Get arrested","Refuel"],1],["When pulled over, you should keep your hands:",["In your pockets","On the steering wheel, visible","Behind your back","On your phone"],1],["'Deadheading' means driving:",["With a full load","Empty, without cargo","At night only","In reverse"],1],["If your ELD malfunctions, you should:",["Ignore it","Switch to paper logs and report it","Stop driving forever","Call 911"],1],["'Chain up' is necessary because of:",["Hot weather","Snow and ice","Heavy traffic","Fog only"],1],["The standard legal gross weight limit is usually:",["65,000 lbs","80,000 lbs","100,000 lbs","50,000 lbs"],1],["'Can you give me an estimate?' is asked to a:",["Police officer","Mechanic, about repair cost","Customer","Dispatcher"],1],["'Hit the road' is an idiom meaning:",["Crash","Start a trip","Stop","Take a nap"],1],["The polite way to ask someone to repeat themselves is:",["'What?'","'Can you repeat that, please?'","Stay silent","'Huh?'"],1],["A 'lumper' is hired to:",["Drive the truck","Load or unload cargo","Inspect brakes","Fix the engine"],1],["'Per diem' pay is meant to cover:",["Truck repairs","Daily meals and expenses on the road","Insurance","Bonuses"],1],["The main goal of this 60-day course was to help you:",["Pass a grammar test","Communicate confidently in real trucking situations","Learn to read maps only","Memorize idioms only"],1]],"sp":["FINAL EXAM: Roleplay a complete trip — greet a dispatcher, do a pre-trip inspection, pass a weigh station, handle a DOT stop, report a small delay, and make a delivery with the customer. Speak with confidence!","YAKUNIY IMTIHON: To'liq safarni o'ynang — dispetcher bilan salomlashing, pre-trip tekshiruvini o'tkazing, tarozi bekatidan o'ting, DOT to'xtatilishini boshdan kechiring, kichik kechikish haqida xabar bering va mijoz bilan yetkazib berishni amalga oshiring. Ishonch bilan gapiring!"]},
];

